171:         if (IsGameRunning || (_activeProcess is { HasExited: false })) return Task.CompletedTask;
172: 
173:         IsProcessing = true;
174:         ProgressValue = 50;
175:         ProgressText = "Launching game engine (nds_runner)...";
176: 
177:         try
178:         {
179:             var proc = RomPreparationService.LaunchGame(RomPath);
180:             _activeProcess = proc;
181:             IsGameRunning = true;
182:             int exitedHandled = 0;
