184:             void HandleExit()
185:             {
186:                 if (Interlocked.Exchange(ref exitedHandled, 1) != 0) return;
187:                 var exitCode = 0;
188:                 try { exitCode = proc.ExitCode; } catch { }
189:                 void ApplyExitUi()
190:                 {
191:                     if (ReferenceEquals(_activeProcess, proc))
192:                         _activeProcess = null;
193:                     IsGameRunning = false;
194:                     ProgressValue = exitCode == 0 ? 100 : 0;
195:                     ProgressText = exitCode == 0 ? "Ready to Play" : $"Engine Exited ({exitCode})";
196:                     StatusMessage = exitCode == 0
197:                         ? $"Verified Clean ROM: Pokémon Mystery Dungeon: Explorers of Sky [{RomRegion}]"
198:                         : $"nds_runner exited with code {exitCode}. Check nds_runner.log for details.";
199:                 }
200:                 if (Application.Current != null)
201:                     Dispatcher.UIThread.Post(ApplyExitUi);
202:                 else
203:                     ApplyExitUi();
204:             }
205: 
206:             proc.EnableRaisingEvents = true;
207:             proc.Exited += (_, _) => HandleExit();
208:             if (proc.HasExited)
209:                 HandleExit();
210: 
211:             ProgressValue = 100;
212:             ProgressText = "Game Running";
213:             StatusMessage = "SkyRecompiled is active. Enjoy your dungeon exploration!";
214:         }
215:         catch (Exception ex)
216:         {
217:             IsGameRunning = false;
218:             _activeProcess = null;
219:             StatusMessage = $"Failed to launch engine: {ex.Message}";
220:             ProgressText = "Launch Error";
