46:     public static Dictionary<string, string> LoadSettings(string? settingsFile = null)
47:     {
48:         var result = new Dictionary<string, string>(StringComparer.Ordinal);
49:         var path = settingsFile ?? GetSettingsPath();
50:         if (!File.Exists(path)) return result;
51: 
52:         foreach (var line in File.ReadAllLines(path))
53:         {
54:             var trimmed = line.Trim();
55:             if (string.IsNullOrEmpty(trimmed) || trimmed.StartsWith('#') || !trimmed.Contains('='))
56:                 continue;
57:             var parts = trimmed.Split('=', 2);
58:             if (parts.Length == 2)
59:             {
60:                 var key = parts[0].Trim();
61:                 var val = parts[1].Trim().Trim('"', '\'');
62:                 if (!string.IsNullOrEmpty(key))
63:                     result[key] = val;
64:             }
65:         }
66:         return result;
67:     }
