69:     public static void SaveSettingsAtomic(Dictionary<string, string> settings, string? settingsFile = null)
70:     {
71:         var targetPath = settingsFile ?? GetSettingsPath();
72:         var dir = Path.GetDirectoryName(targetPath);
73:         if (!string.IsNullOrEmpty(dir))
74:             Directory.CreateDirectory(dir);
75: 
76:         var lines = new List<string> { "# SkyRecompiled Configuration" };
77:         foreach (var kv in settings.OrderBy(p => p.Key, StringComparer.Ordinal))
78:         {
79:             lines.Add($"{kv.Key} = \"{kv.Value}\"");
80:         }
81:         var content = string.Join(Environment.NewLine, lines) + Environment.NewLine;
82:         var tmpPath = Path.Combine(dir ?? ".", $".{Path.GetFileName(targetPath)}.{Guid.NewGuid():N}.tmp");
83:         try
84:         {
85:             File.WriteAllText(tmpPath, content);
86:             File.Move(tmpPath, targetPath, overwrite: true);
87:         }
88:         finally
89:         {
90:             if (File.Exists(tmpPath))
91:                 File.Delete(tmpPath);
92:         }
93:     }
