138:     public static async Task<RomInfo> VerifyRomAsync(string path, IProgress<(double Progress, string Status)>? progress = null, CancellationToken ct = default)
139:     {
140:         if (!File.Exists(path))
141:             return new RomInfo(path, "Unknown", "", false);
142: 
143:         var fileInfo = new FileInfo(path);
144:         long totalBytes = fileInfo.Length;
145:         if (totalBytes == 0)
146:             return new RomInfo(path, "Unknown", "", false);
147: 
148:         using var sha1 = SHA1.Create();
149:         await using var stream = File.OpenRead(path);
150:         byte[] buffer = new byte[1024 * 1024]; // 1MB chunks
151:         long readBytes = 0;
152:         int bytesRead;
153: 
154:         while ((bytesRead = await stream.ReadAsync(buffer.AsMemory(0, buffer.Length), ct)) > 0)
155:         {
156:             sha1.TransformBlock(buffer, 0, bytesRead, null, 0);
157:             readBytes += bytesRead;
158:             var pct = ((double)readBytes / totalBytes) * 100.0;
159:             progress?.Report((pct, $"Verifying cartridge ROM... {pct:0}%"));
160:         }
161: 
162:         sha1.TransformFinalBlock(buffer, 0, 0);
163:         var hashHex = Convert.ToHexString(sha1.Hash ?? Array.Empty<byte>()).ToLowerInvariant();
164: 
165:         if (hashHex == CleanUsaSha1)
166:             return new RomInfo(path, "USA (NA)", hashHex, true);
167:         if (hashHex == CleanEuSha1)
168:             return new RomInfo(path, "Europe (EU)", hashHex, true);
169: 
170:         return new RomInfo(path, "Unsupported / Modified", hashHex, false);
171:     }
