173:     public static (string RunnerPath, string ConfigPath) LocateEngineBinaries()
174:     {
175:         var exeName = OperatingSystem.IsWindows() ? "nds_runner.exe" : "nds_runner";
176:         var appDir = AppDomain.CurrentDomain.BaseDirectory;
177: 
178:         // Try standard layout candidates
179:         string[] runnerCandidates =
180:         {
181:             Path.Combine(appDir, exeName),
182:             Path.Combine(appDir, "..", "MacOS", exeName),
183:             Path.Combine(appDir, "bin", exeName),
184:             Path.Combine(appDir, "..", "..", "..", "build", "runner", exeName),
185:             Path.Combine(appDir, "..", "..", "..", "..", "build", "runner", exeName)
186:         };
187: 
188:         string? foundRunner = null;
189:         foreach (var c in runnerCandidates)
190:         {
191:             var full = Path.GetFullPath(c);
192:             if (File.Exists(full)) { foundRunner = full; break; }
193:         }
194: 
195:         string[] configCandidates =
196:         {
197:             Path.Combine(appDir, "game.toml"),
198:             Path.Combine(appDir, "Resources", "game.toml"),
199:             Path.Combine(appDir, "..", "Resources", "game.toml"),
200:             Path.Combine(appDir, "config", "game.toml"),
201:             Path.Combine(appDir, "..", "..", "..", "config", "game.toml"),
202:             Path.Combine(appDir, "..", "..", "..", "..", "config", "game.toml")
203:         };
204: 
205:         string? foundConfig = null;
206:         foreach (var c in configCandidates)
207:         {
208:             var full = Path.GetFullPath(c);
209:             if (File.Exists(full)) { foundConfig = full; break; }
210:         }
211: 
212:         if (foundRunner == null)
213:             throw new FileNotFoundException($"Could not locate {exeName} engine executable.");
214:         if (foundConfig == null)
215:             throw new FileNotFoundException("Could not locate game.toml cartridge configuration.");
216: 
217:         return (foundRunner, foundConfig);
218:     }
