239:             RedirectStandardOutput = true,
240:             RedirectStandardError = true
241:         };
242:         psi.ArgumentList.Add(consoleDir);
243:         psi.ArgumentList.Add("--interactive");
244:         psi.ArgumentList.Add("--config");
245:         psi.ArgumentList.Add(configPath);
246:         psi.ArgumentList.Add("--rom");
