248:         psi.ArgumentList.Add("--save-path");
249:         psi.ArgumentList.Add(savePath);
250:         psi.ArgumentList.Add("--savestate-dir");
251:         psi.ArgumentList.Add(savestateDir);
252:         psi.ArgumentList.Add("--runtime-settings-path");
253:         psi.ArgumentList.Add(skySettingsPath);
254:         psi.ArgumentList.Add("--rtc-host");
