259:         }
260:         catch
261:         {
262:             // Diagnostic logging must never prevent the game from launching.
263:         }
264: 
265:         var proc = Process.Start(psi);
266:         if (proc == null)
267:             throw new InvalidOperationException("Failed to launch nds_runner process.");
268: 
269:         void AppendRunnerLog(string? line)
270:         {
271:             if (line is null) return;
272:             try { File.AppendAllText(logPath, line + Environment.NewLine); }
273:             catch { }
274:         }
275:         proc.OutputDataReceived += (_, e) => AppendRunnerLog(e.Data);
276:         proc.ErrorDataReceived += (_, e) => AppendRunnerLog(e.Data);
277:         proc.BeginOutputReadLine();
278:         proc.BeginErrorReadLine();
279: 
280:         return proc;
281:     }
