25: const WONDER_MAIL_CHARSET_STR = "&67NPR89F0+#STXY45MCHJ-K12=%3Q@W";
26: const WONDER_MAIL_CHARSET = new Set(WONDER_MAIL_CHARSET_STR);
27: const CHAR_MAP = new Map<string, number>();
28: for (let i = 0; i < WONDER_MAIL_CHARSET_STR.length; i++) {
29:   CHAR_MAP.set(WONDER_MAIL_CHARSET_STR[i], i);
