39: function isValidPassword(clean: string, expectedLen: number): boolean {
40:   if (clean.length !== expectedLen) return false;
41:   for (let i = 0; i < clean.length; i++) {
42:     if (!WONDER_MAIL_CHARSET.has(clean[i])) return false;
43:   }
44:   return true;
45: }
