47: function computeChecksum(symbols: number[]): number {
48:   let c1 = 0;
49:   let c2 = 0;
50:   for (let i = 0; i < 52; i++) {
51:     c1 = (c1 + symbols[i]) & 0x1F;
52:     c2 = (c2 + c1) & 0x1F;
53:   }
54:   return (c1 << 5) | c2;
55: }
56: 
57: export function parseRescueMail(clean: string): ParsedRescueMail | null {
58:   if (clean.length !== 54) return null;
59:   const symbols: number[] = [];
60:   for (let i = 0; i < clean.length; i++) {
61:     const val = CHAR_MAP.get(clean[i]);
62:     if (val === undefined) return null;
63:     symbols.push(val);
64:   }
65: 
66:   const expectedChk = (symbols[52] << 5) | symbols[53];
67:   const actualChk = computeChecksum(symbols);
68:   if (expectedChk !== actualChk) return null;
69: 
70:   const bits: number[] = [];
71:   for (let i = 0; i < 52; i++) {
72:     for (let b = 4; b >= 0; b--) {
73:       bits.push((symbols[i] >> b) & 1);
74:     }
75:   }
76: 
77:   let bitPos = 0;
78:   function readBits(n: number): number {
79:     let val = 0;
80:     for (let i = 0; i < n; i++) {
81:       val = val * 2 + bits[bitPos++];
82:     }
83:     return val;
84:   }
85: 
86:   const kind = readBits(3); // 1 = SOS, 2 = A-OK, 3 = THANK-YOU
87:   if (kind < 1 || kind > 3) return null;
88:   const dungeonId = readBits(7);
89:   const floor = readBits(7);
90:   const clientSpecies = readBits(11);
91:   const rescueId = readBits(32);
92:   const revivesLeft = readBits(3);
93:   const nameLen = readBits(4);
94:   if (nameLen > 10) return null;
95: 
96:   let teamName = "";
97:   for (let i = 0; i < nameLen; i++) {
98:     teamName += String.fromCharCode(readBits(8));
99:   }
100: 
101:   return { kind, dungeonId, floor, clientSpecies, rescueId, revivesLeft, teamName };
