112: async function readJsonBody<T>(request: Request): Promise<T | null> {
113:   try {
114:     const parsed = await request.json();
115:     if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
116:       return null;
117:     }
118:     return parsed as T;
119:   } catch {
120:     return null;
121:   }
122: }
