124: const CORS_HEADERS = {
125:   "Access-Control-Allow-Origin": "*",
126:   "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
127:   "Access-Control-Allow-Headers": "Content-Type, Authorization",
128:   "Content-Type": "application/json",
129: };
