142: function resolveExpectedRescueId(row: { rescue_id?: number | null; sos_password?: string | null }): number | null {
143:   if (typeof row.rescue_id === "number" && row.rescue_id !== 0) {
144:     return row.rescue_id;
145:   }
146:   if (typeof row.sos_password === "string") {
147:     const parsed = parseRescueMail(row.sos_password);
148:     if (parsed) return parsed.rescueId;
149:   }
150:   return typeof row.rescue_id === "number" ? row.rescue_id : null;
151: }
