153: export default {
154:   async fetch(request: Request, env: Env): Promise<Response> {
155:     if (request.method === "OPTIONS") {
156:       return new Response(null, { headers: CORS_HEADERS });
157:     }
158: 
159:     const url = new URL(request.url);
160:     const path = url.pathname;
161:     const now = Math.floor(Date.now() / 1000);
162: 
163:     try {
164:       // ───────────────────────────────────────────────────────────────────────
165:       // Health check
166:       // ───────────────────────────────────────────────────────────────────────
167:       if (path === "/health" || path === "/") {
168:         return jsonResponse({
169:           status: "healthy",
170:           service: "SkyRecompiled Online Rescue Board",
171:           timestamp: now,
172:         });
173:       }
174: 
175:       // ───────────────────────────────────────────────────────────────────────
176:       // POST /v1/rescues (Submit SOS Request)
177:       // ───────────────────────────────────────────────────────────────────────
178:       if (path === "/v1/rescues" && request.method === "POST") {
179:         const body = await readJsonBody<{
180:           dungeon_id?: number;
181:           floor?: number;
182:           team_name?: string;
183:           client_species?: number;
184:           sos_password?: string;
185:           friend_code?: string;
186:         }>(request);
187:         if (!body) {
188:           return errorResponse("Invalid JSON request body", 400);
189:         }
190: 
191:         if (
192:           typeof body.dungeon_id !== "number" ||
193:           !Number.isInteger(body.dungeon_id) ||
194:           typeof body.floor !== "number" ||
195:           !Number.isInteger(body.floor) ||
196:           typeof body.team_name !== "string" ||
197:           body.team_name.length === 0 ||
198:           typeof body.client_species !== "number" ||
199:           !Number.isInteger(body.client_species) ||
200:           typeof body.sos_password !== "string" ||
201:           body.sos_password.length === 0
202:         ) {
203:           return errorResponse("Missing or invalid required fields (dungeon_id, floor, team_name, client_species, sos_password)");
204:         }
205: 
206:         const cleanSos = normalizePassword(body.sos_password);
207:         if (!isValidPassword(cleanSos, 54)) {
208:           return errorResponse("Invalid SOS password: must be 54 characters from Explorers of Sky charset");
209:         }
210: 
211:         const sosInfo = parseRescueMail(cleanSos);
212:         if (!sosInfo || sosInfo.kind !== 1) {
213:           return errorResponse("Invalid SOS password: checksum verification failed or not an SOS request");
214:         }
215:         const teamName = body.team_name.slice(0, 10);
216:         if (
217:           sosInfo.dungeonId !== body.dungeon_id ||
218:           sosInfo.floor !== body.floor ||
219:           sosInfo.clientSpecies !== body.client_species ||
220:           sosInfo.teamName !== teamName
221:         ) {
222:           return errorResponse("SOS password metadata does not match submission fields");
223:         }
224: 
225:         const id = crypto.randomUUID();
226:         const ownerToken = crypto.randomUUID();
227:         const friendCode = typeof body.friend_code === "string" ? body.friend_code.slice(0, 20) : null;
228: 
229:         try {
230:           await env.DB.prepare(
231:             `INSERT INTO rescues (
232:               id, rescue_id, dungeon_id, floor, team_name, client_species, sos_password,
233:               status, friend_code, owner_token, created_at, updated_at
234:             ) VALUES (?, ?, ?, ?, ?, ?, ?, 'open', ?, ?, ?, ?)`
235:           )
236:             .bind(
237:               id,
238:               sosInfo.rescueId,
239:               body.dungeon_id,
240:               body.floor,
241:               teamName,
242:               body.client_species,
243:               cleanSos,
244:               friendCode,
245:               ownerToken,
246:               now,
247:               now
248:             )
249:             .run();
250:         } catch (insertErr: unknown) {
251:           const msg = insertErr instanceof Error ? insertErr.message : String(insertErr);
252:           if (/UNIQUE constraint failed|SQLITE_CONSTRAINT/i.test(msg)) {
253:             return errorResponse("An active rescue with this SOS identity already exists", 409);
254:           }
255:           throw insertErr;
256:         }
257: 
258:         return jsonResponse({
259:           success: true,
260:           id,
261:           rescue_id: sosInfo.rescueId,
262:           owner_token: ownerToken,
263:           status: "open",
264:           message: "Rescue request posted successfully to the Pelipper Board!",
265:         }, 201);
266:       }
267: 
268:       // ───────────────────────────────────────────────────────────────────────
269:       // GET /v1/rescues (List Rescues)
270:       // ───────────────────────────────────────────────────────────────────────
271:       if (path === "/v1/rescues" && request.method === "GET") {
272:         // Auto-revert expired claims back to 'open'
