274:           `UPDATE rescues SET status = 'open', claim_expires_at = NULL, rescuer_team_name = NULL, claim_token = NULL, updated_at = ?
275:            WHERE status = 'claimed' AND claim_expires_at IS NOT NULL AND claim_expires_at < ?`
276:         )
277:           .bind(now, now)
278:           .run();
279: 
280:         const statusParam = url.searchParams.get("status") || "open";
281:         if (!VALID_STATUSES.has(statusParam)) {
282:           return errorResponse("Invalid status filter", 400);
283:         }
284: 
285:         const dungeonIdRaw = url.searchParams.get("dungeon_id");
286:         let parsedDungeonId: number | null = null;
287:         if (dungeonIdRaw !== null) {
288:           if (!/^\d+$/.test(dungeonIdRaw)) {
289:             return errorResponse("Invalid dungeon_id parameter", 400);
290:           }
291:           parsedDungeonId = parseInt(dungeonIdRaw, 10);
292:           if (parsedDungeonId < 0 || parsedDungeonId > 127) {
