294:           }
295:         }
296: 
297:         const limitRaw = url.searchParams.get("limit");
298:         const offsetRaw = url.searchParams.get("offset");
299:         if (limitRaw !== null && !/^\d+$/.test(limitRaw)) {
300:           return errorResponse("Invalid limit parameter", 400);
301:         }
302:         if (offsetRaw !== null && !/^\d+$/.test(offsetRaw)) {
303:           return errorResponse("Invalid offset parameter", 400);
304:         }
305:         const limit = Math.min(Math.max(parseInt(limitRaw || "50", 10), 1), 100);
306:         const offset = Math.max(parseInt(offsetRaw || "0", 10), 0);
307: 
308:         let query = "SELECT * FROM rescues WHERE status = ?";
309:         const bindings: (string | number)[] = [statusParam];
310: 
311:         if (parsedDungeonId !== null) {
312:           query += " AND dungeon_id = ?";
313:           bindings.push(parsedDungeonId);
314:         }
315: 
316:         query += " ORDER BY created_at DESC LIMIT ? OFFSET ?";
317:         bindings.push(limit, offset);
