860: void SkySettingsOverlay::ScaleAudioSamplesInt16(std::span<int16_t> pcm_samples) const noexcept {
861:     const int eff_vol = GetEffectiveAudioVolumePercent();
862:     if (eff_vol >= 100) {
863:         return;
864:     }
865:     if (eff_vol <= 0) {
866:         std::fill(pcm_samples.begin(), pcm_samples.end(), int16_t{0});
867:         return;
868:     }
869:     for (int16_t& sample : pcm_samples) {
870:         const int32_t scaled = (static_cast<int32_t>(sample) * eff_vol) / 100;
871:         sample = static_cast<int16_t>(std::clamp<int32_t>(scaled, -32768, 32767));
872:     }
873: }
