875: DsButtonMapping SkySettingsOverlay::GetActiveButtonMapping() const noexcept {
876:     DsButtonMapping map{};
877:     const auto& bindings = state_.controller_bindings;
878:     auto bit_for_code = [&bindings](int code, int slot) {
879:         if (slot < 0 || static_cast<size_t>(slot) >= bindings.size()) return uint16_t{0};
880:         return bindings[static_cast<size_t>(slot)] == code
881:             ? kDsBits[static_cast<size_t>(slot)] : uint16_t{0};
882:     };
883:     map.confirm_bit = bit_for_code(state_.controller_bindings[4], 4);
884:     map.cancel_bit = bit_for_code(state_.controller_bindings[5], 5);
885:     map.menu_bit = bit_for_code(state_.controller_bindings[6], 6);
886:     map.sort_bit = bit_for_code(state_.controller_bindings[7], 7);
887:     map.shoulder_l_bit = bit_for_code(state_.controller_bindings[8], 8);
888:     map.shoulder_r_bit = bit_for_code(state_.controller_bindings[9], 9);
889:     return map;
890: }
