892: uint16_t SkySettingsOverlay::RemapDsKeyinputMask(uint16_t logical_pressed_mask) const noexcept {
893:     constexpr uint16_t kActionBitsMask =
894:         (1u << 0) | (1u << 1) | (1u << 8) | (1u << 9) | (1u << 10) | (1u << 11);
895:     const DsButtonMapping map = GetActiveButtonMapping();
896:     uint16_t out = logical_pressed_mask & static_cast<uint16_t>(~kActionBitsMask);
897:     if ((logical_pressed_mask & (1u << 0)) != 0u) {
898:         out |= map.confirm_bit;
899:     }
900:     if ((logical_pressed_mask & (1u << 1)) != 0u) {
901:         out |= map.cancel_bit;
902:     }
903:     if ((logical_pressed_mask & (1u << 8)) != 0u) {
904:         out |= map.shoulder_r_bit;
905:     }
906:     if ((logical_pressed_mask & (1u << 9)) != 0u) {
907:         out |= map.shoulder_l_bit;
908:     }
909:     if ((logical_pressed_mask & (1u << 10)) != 0u) {
910:         out |= map.menu_bit;
911:     }
912:     if ((logical_pressed_mask & (1u << 11)) != 0u) {
913:         out |= map.sort_bit;
914:     }
915:     return out;
916: }
