/// <summary>
/// Manages cartridge SHA-1 verification, cross-platform user storage paths, atomic
/// launcher settings persistence, engine binary discovery, and launching <c>nds_runner</c>.
/// </summary>
public class RomPreparationService
{
    public const string CleanUsaSha1 = "5fa96ca8d8dd6405d6cd2bad73ed68bc73a9d152";
    public const string CleanEuSha1 = "c838a5adf1ed32d2da8454976e5b1a1aa189c139";

    public static readonly IReadOnlySet<string> DefaultValidSha1s = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        CleanUsaSha1,
        CleanEuSha1,
    };

    private static readonly object LogLock = new();

    public static string GetUserStorageDir()
    {
        if (OperatingSystem.IsMacOS())
        {
            var home = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
            return Path.Combine(home, "Library", "Application Support", "SkyRecompiled");
        }
        if (OperatingSystem.IsWindows())
        {
            var appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
            return Path.Combine(appData, "SkyRecompiled");
        }

        var xdg = Environment.GetEnvironmentVariable("XDG_DATA_HOME");
        var baseDir = !string.IsNullOrEmpty(xdg)
            ? xdg
            : Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".local", "share");
        return Path.Combine(baseDir, "SkyRecompiled");
    }

    public static string GetSettingsPath() => Path.Combine(GetUserStorageDir(), "settings.toml");
    public static string GetSkySettingsPath() => Path.Combine(GetUserStorageDir(), "sky_settings.toml");
    public static string GetSavesDir() => Path.Combine(GetUserStorageDir(), "saves");
    public static string GetSavesPath() => Path.Combine(GetSavesDir(), "pmdsky.sav");
    public static string GetSavestatesDir() => Path.Combine(GetUserStorageDir(), "savestates");
    public static string GetConsoleDir() => Path.Combine(GetUserStorageDir(), "console");
    public static string GetModsDir() => Path.Combine(GetUserStorageDir(), "mods");
    public static string GetModStatePath() => Path.Combine(GetUserStorageDir(), "mods_state.json");
    public static string GetActiveModsManifestPath() => Path.Combine(GetUserStorageDir(), "active_mods.json");
    public static string GetRescueTokensPath() => Path.Combine(GetUserStorageDir(), "rescue_tokens.json");
    public static string GetLogPath() => Path.Combine(GetUserStorageDir(), "nds_runner.log");

    public static Dictionary<string, string> LoadSettings(string? settingsFile = null)
    {
        var result = new Dictionary<string, string>(StringComparer.Ordinal);
        var path = settingsFile ?? GetSettingsPath();
        if (!File.Exists(path)) return result;

        foreach (var line in File.ReadAllLines(path))
        {
            var trimmed = line.Trim();
            if (string.IsNullOrEmpty(trimmed) || trimmed.StartsWith('#') || !trimmed.Contains('='))
                continue;
            var parts = trimmed.Split('=', 2);
            if (parts.Length == 2)
            {
                var key = parts[0].Trim();
                var val = parts[1].Trim().Trim('"', '\'');
                if (!string.IsNullOrEmpty(key))
                    result[key] = val;
            }
        }
        return result;
    }

    public static void SaveSettingsAtomic(Dictionary<string, string> settings, string? settingsFile = null)
    {
        var targetPath = settingsFile ?? GetSettingsPath();
        var dir = Path.GetDirectoryName(targetPath);
        if (!string.IsNullOrEmpty(dir))
            Directory.CreateDirectory(dir);

        var lines = new List<string> { "# SkyRecompiled Configuration" };
        foreach (var kv in settings.OrderBy(p => p.Key, StringComparer.Ordinal))
        {
            var sanitizedKey = kv.Key.Replace("\r", "").Replace("\n", "").Trim();
            if (string.IsNullOrEmpty(sanitizedKey))
                continue;
            var sanitizedVal = (kv.Value ?? string.Empty).Replace("\r", "").Replace("\n", "");
            lines.Add($"{sanitizedKey} = \"{sanitizedVal}\"");
        }
        var content = string.Join(Environment.NewLine, lines) + Environment.NewLine;
        var tmpPath = Path.Combine(dir ?? ".", $".{Path.GetFileName(targetPath)}.{Guid.NewGuid():N}.tmp");
        try
        {
            File.WriteAllText(tmpPath, content);
            File.Move(tmpPath, targetPath, overwrite: true);
        }
        finally
        {
            if (File.Exists(tmpPath))
                File.Delete(tmpPath);
        }
    }

    public static void UpdateSettings(IDictionary<string, string> updates, string? settingsFile = null)
    {
        var current = LoadSettings(settingsFile);
        foreach (var kv in updates)
        {
            current[kv.Key] = kv.Value;
        }
        SaveSettingsAtomic(current, settingsFile);
    }

    public static LauncherPreferences LoadPreferences(string? settingsFile = null)
    {
        var raw = LoadSettings(settingsFile);
        var prefs = new LauncherPreferences();
        if (raw.TryGetValue("rescue_endpoint", out var ep))
            prefs.RescueEndpoint = LauncherPreferences.NormalizeEndpoint(ep);
        if (raw.TryGetValue("team_name", out var team))
            prefs.TeamName = LauncherPreferences.NormalizeTeamName(team);
        if (raw.TryGetValue("rescue_offline", out var offline))
            prefs.RescueOfflineMode = string.Equals(offline, "true", StringComparison.OrdinalIgnoreCase) || offline == "1";
        return prefs;
    }

    public static void SavePreferences(LauncherPreferences prefs, string? settingsFile = null)
    {
        UpdateSettings(new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["rescue_endpoint"] = LauncherPreferences.NormalizeEndpoint(prefs.RescueEndpoint),
            ["team_name"] = LauncherPreferences.NormalizeTeamName(prefs.TeamName),
            ["rescue_offline"] = prefs.RescueOfflineMode ? "true" : "false",
        }, settingsFile);
    }

    public static string? LoadSavedRomPath(string? settingsFile = null)
    {
        try
        {
            var settings = LoadSettings(settingsFile);
            if (settings.TryGetValue("rom_path", out var val) && File.Exists(val))
                return val;
        }
        catch
        {
            // Ignore any permission or read issues
        }
        return null;
    }

    public static void SaveRomPath(string romPath, string? settingsFile = null)
    {
        try
        {
            var settings = LoadSettings(settingsFile);
            settings["rom_path"] = romPath;
            SaveSettingsAtomic(settings, settingsFile);
        }
        catch
        {
            // Ignore write errors
        }
    }

    public static void ClearSavedRomPath(string? settingsFile = null)
    {
        try
        {
            var settings = LoadSettings(settingsFile);
            if (settings.Remove("rom_path"))
                SaveSettingsAtomic(settings, settingsFile);
        }
        catch
        {
            // Ignore write errors
        }
    }

    public static Task<RomInfo> VerifyRomAsync(
        string path,
        IProgress<(double Progress, string Status)>? progress = null,
        CancellationToken ct = default)
        => VerifyRomAsync(path, DefaultValidSha1s, progress, ct);

    public static async Task<RomInfo> VerifyRomAsync(
        string path,
        IReadOnlySet<string> acceptedSha1s,
        IProgress<(double Progress, string Status)>? progress = null,
        CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            return new RomInfo(path, "Unknown", "", false, 0);

        var fileInfo = new FileInfo(path);
        long totalBytes = fileInfo.Length;
        if (totalBytes == 0)
            return new RomInfo(path, "Unknown", "", false, 0);

        using var sha1 = SHA1.Create();
        await using var stream = File.OpenRead(path);
        byte[] buffer = new byte[1024 * 1024]; // 1MB chunks
        long readBytes = 0;
        int bytesRead;

        while ((bytesRead = await stream.ReadAsync(buffer.AsMemory(0, buffer.Length), ct)) > 0)
        {
            ct.ThrowIfCancellationRequested();
            sha1.TransformBlock(buffer, 0, bytesRead, null, 0);
            readBytes += bytesRead;
            var pct = ((double)readBytes / totalBytes) * 100.0;
            progress?.Report((pct, $"Verifying cartridge ROM... {pct:0}%"));
        }

        sha1.TransformFinalBlock(buffer, 0, 0);
        var hashHex = Convert.ToHexString(sha1.Hash ?? Array.Empty<byte>()).ToLowerInvariant();

        if (hashHex == CleanUsaSha1)
            return new RomInfo(path, "USA (NA)", hashHex, true, totalBytes);
        if (hashHex == CleanEuSha1)
            return new RomInfo(path, "Europe (EU)", hashHex, true, totalBytes);
        if (acceptedSha1s.Contains(hashHex))
            return new RomInfo(path, "Verified Custom", hashHex, true, totalBytes);

        return new RomInfo(path, "Unsupported / Modified", hashHex, false, totalBytes);
    }

    public static (string RunnerPath, string ConfigPath) LocateEngineBinaries(string? baseDirOverride = null)
    {
        var exeName = OperatingSystem.IsWindows() ? "nds_runner.exe" : "nds_runner";
        var appDir = string.IsNullOrWhiteSpace(baseDirOverride) ? AppContext.BaseDirectory : baseDirOverride;

        string[] runnerCandidates =
        {
            Path.Combine(appDir, exeName),
            Path.Combine(appDir, "bin", exeName),
            Path.Combine(appDir, "..", "MacOS", exeName),
            Path.Combine(appDir, "..", "..", "..", "build", "runner", exeName),
            Path.Combine(appDir, "..", "..", "..", "..", "build", "runner", exeName),
            Path.Combine(appDir, "..", "..", "..", "..", "..", "build", "runner", exeName),
            Path.Combine(appDir, "..", "..", "..", "build", "runner-fallback", exeName),
            Path.Combine(appDir, "..", "..", "..", "..", "build", "runner-fallback", exeName),
            Path.Combine(appDir, "..", "..", "..", "..", "..", "build", "runner-fallback", exeName),
        };

        string? foundRunner = null;
        foreach (var c in runnerCandidates)
        {
            var full = Path.GetFullPath(c);
            if (File.Exists(full)) { foundRunner = full; break; }
        }

        string[] configCandidates =
        {
            Path.Combine(appDir, "game.toml"),
            Path.Combine(appDir, "Resources", "game.toml"),
            Path.Combine(appDir, "..", "Resources", "game.toml"),
            Path.Combine(appDir, "config", "game.toml"),
            Path.Combine(appDir, "..", "config", "game.toml"),
            Path.Combine(appDir, "..", "..", "..", "config", "game.toml"),
            Path.Combine(appDir, "..", "..", "..", "..", "config", "game.toml"),
            Path.Combine(appDir, "..", "..", "..", "..", "..", "config", "game.toml"),
        };

        string? foundConfig = null;
        foreach (var c in configCandidates)
        {
            var full = Path.GetFullPath(c);
            if (File.Exists(full)) { foundConfig = full; break; }
        }

        if (foundRunner == null)
            throw new FileNotFoundException($"Could not locate {exeName} engine executable.");
        if (foundConfig == null)
            throw new FileNotFoundException("Could not locate game.toml cartridge configuration.");

        return (foundRunner, foundConfig);
    }

    public static bool TryLocateEngineBinaries(
        out string? runnerPath,
        out string? configPath,
        out string? error,
        string? baseDirOverride = null)
    {
        try
        {
            var located = LocateEngineBinaries(baseDirOverride);
            runnerPath = located.RunnerPath;
            configPath = located.ConfigPath;
            error = null;
            return true;
        }
        catch (Exception ex)
        {
            runnerPath = null;
            configPath = null;
            error = ex.Message;
            return false;
        }
    }

    /// <summary>
    /// Headless runner verification for CI and CLI smoke checks (<c>--check-runner</c>).
    /// </summary>
    public static int CheckRunner(string? baseDirOverride = null)
    {
        if (!TryLocateEngineBinaries(out var runnerPath, out var configPath, out var error, baseDirOverride) ||
            runnerPath == null || configPath == null)
        {
            Console.Error.WriteLine($"[SkyRecompiled] {error}");
            return 1;
        }

        var psi = new ProcessStartInfo
        {
            FileName = runnerPath,
            UseShellExecute = false,
            WorkingDirectory = Path.GetDirectoryName(runnerPath)!,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
        };
        psi.ArgumentList.Add("--help");

        try
        {
            using var proc = Process.Start(psi);
            if (proc == null)
            {
                Console.Error.WriteLine("[SkyRecompiled] Failed to spawn nds_runner.");
                return 1;
            }
            var stdout = proc.StandardOutput.ReadToEnd();
            var stderr = proc.StandardError.ReadToEnd();
            proc.WaitForExit();
            if (!string.IsNullOrEmpty(stdout))
                Console.Out.Write(stdout);
            if (!string.IsNullOrEmpty(stderr))
                Console.Error.Write(stderr);
            return proc.ExitCode;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"[SkyRecompiled] Runner check failed: {ex.Message}");
            return 1;
        }
    }

    public static Process LaunchGame(string romPath, Action<string>? onLogLine = null)
    {
        var (runnerBin, configPath) = LocateEngineBinaries();
        var savePath = GetSavesPath();
        var consoleDir = GetConsoleDir();
        var userDir = GetUserStorageDir();
        var savestateDir = GetSavestatesDir();

        Directory.CreateDirectory(Path.GetDirectoryName(savePath)!);
        Directory.CreateDirectory(consoleDir);
        Directory.CreateDirectory(savestateDir);

        var skySettingsPath = GetSkySettingsPath();
        var logPath = GetLogPath();
        var psi = new ProcessStartInfo
        {
            FileName = runnerBin,
            UseShellExecute = false,
            WorkingDirectory = Path.GetDirectoryName(runnerBin)!,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
        };
        psi.ArgumentList.Add(consoleDir);
        psi.ArgumentList.Add("--interactive");
        psi.ArgumentList.Add("--config");
        psi.ArgumentList.Add(configPath);
        psi.ArgumentList.Add("--rom");
        psi.ArgumentList.Add(romPath);
        psi.ArgumentList.Add("--save-path");
        psi.ArgumentList.Add(savePath);
        psi.ArgumentList.Add("--savestate-dir");
        psi.ArgumentList.Add(savestateDir);
        psi.ArgumentList.Add("--runtime-settings-path");
        psi.ArgumentList.Add(skySettingsPath);
        psi.ArgumentList.Add("--rtc-host");

        var cmdBanner = $"$ {psi.FileName} {string.Join(" ", psi.ArgumentList)}";
        try
        {
            lock (LogLock)
            {
                File.WriteAllText(logPath, cmdBanner + Environment.NewLine);
            }
        }
        catch
        {
            // Diagnostic logging must never prevent the game from launching.
        }
        onLogLine?.Invoke(cmdBanner);

        var proc = Process.Start(psi);
        if (proc == null)
            throw new InvalidOperationException("Failed to launch nds_runner process.");

        void AppendRunnerLog(string? line)
        {
            if (line is null) return;
            try
            {
                lock (LogLock)
                {
                    File.AppendAllText(logPath, line + Environment.NewLine);
                }
            }
            catch
            {
                // Ignore disk log append failures
            }
            onLogLine?.Invoke(line);
        }

        proc.OutputDataReceived += (_, e) => AppendRunnerLog(e.Data);
        proc.ErrorDataReceived += (_, e) => AppendRunnerLog(e.Data);
        proc.BeginOutputReadLine();
        proc.BeginErrorReadLine();

        return proc;
    }

    public static void OpenPathInOs(string targetPath, bool createDirectory = true)
    {
        if (createDirectory)
            Directory.CreateDirectory(targetPath);

        var fileName = OperatingSystem.IsMacOS() ? "open"
            : OperatingSystem.IsWindows() ? "explorer.exe"
            : "xdg-open";
        var psi = new ProcessStartInfo
        {
            FileName = fileName,
            UseShellExecute = false,
        };
        psi.ArgumentList.Add(targetPath);
        Process.Start(psi);
    }
}

using System;
using System.Globalization;
using System.IO;
using System.Text;
using SkyRecompiled.Launcher.Models;

namespace SkyRecompiled.Launcher.Services;

/// <summary>
/// Reads and atomically writes <c>sky_settings.toml</c> in exact parity with
/// <c>runtime/ui/settings_overlay.cpp</c>.
/// </summary>
public static class SkySettingsService
{
    public static readonly string[] AspectRatioLabels =
    {
        "4:3 (256x192)",
        "16:10 (308x192)",
        "16:9 (342x192)",
        "21:9 (448x192)",
    };

    public static readonly string[] HudLayoutLabels =
    {
        "Dual-Screen (Default)",
        "Hybrid",
    };

    public static readonly string[] RefreshRateLabels =
    {
        "60Hz (Vanilla)",
        "120Hz (ProMotion)",
        "144Hz",
        "240Hz",
        "Uncapped VRR",
    };

    public static readonly string[] ShaderFilterLabels =
    {
        "Nearest",
        "Sharp Bilinear",
        "Pixellate",
        "NDS LCD Grid",
        "CRT Scanline",
    };

    public static readonly string[] ControllerPresetLabels =
    {
        "Standard DS",
        "Modern Dungeon",
        "Swapped B/A",
        "Custom",
    };

    public static SkyRuntimeSettings Load(string? path = null)
    {
        var targetPath = path ?? RomPreparationService.GetSkySettingsPath();
        var settings = new SkyRuntimeSettings();
        if (!File.Exists(targetPath))
            return settings;

        try
        {
            var text = File.ReadAllText(targetPath, Encoding.UTF8);
            ParseInto(text, settings);
        }
        catch
        {
            return new SkyRuntimeSettings();
        }
        return settings;
    }

    public static SkyRuntimeSettings Parse(string tomlText)
    {
        var settings = new SkyRuntimeSettings();
        ParseInto(tomlText, settings);
        return settings;
    }

    private static void ParseInto(string tomlText, SkyRuntimeSettings target)
    {
        foreach (var rawLine in tomlText.Split('\n'))
        {
            var line = rawLine.Trim();
            if (string.IsNullOrEmpty(line) || line.StartsWith('#') || line.StartsWith('['))
                continue;

            var eq = line.IndexOf('=');
            if (eq < 0)
                continue;

            var key = line[..eq].Trim();
            var val = line[(eq + 1)..].Trim();

            switch (key)
            {
                case "aspect_ratio":
                    if (int.TryParse(val, NumberStyles.Integer, CultureInfo.InvariantCulture, out var ar))
                        target.AspectRatio = Math.Clamp(ar, 0, 3);
                    break;
                case "hud_layout":
                    if (int.TryParse(val, NumberStyles.Integer, CultureInfo.InvariantCulture, out var hl))
                        target.HudLayout = Math.Clamp(hl, 0, 1);
                    break;
                case "refresh_rate":
                    if (int.TryParse(val, NumberStyles.Integer, CultureInfo.InvariantCulture, out var rr))
                        target.RefreshRate = Math.Clamp(rr, 0, 4);
                    break;
                case "shader_filter":
                    if (int.TryParse(val, NumberStyles.Integer, CultureInfo.InvariantCulture, out var sf))
                        target.ShaderFilter = Math.Clamp(sf, 0, 4);
                    break;
                case "weather_ambient_bloom":
                    target.WeatherAmbientBloom = val == "true" || val == "1";
                    break;
                case "show_fps_meter":
                    target.ShowFpsMeter = val == "true" || val == "1";
                    break;
                case "volume_percent":
                    if (int.TryParse(val, NumberStyles.Integer, CultureInfo.InvariantCulture, out var vp))
                        target.AudioVolumePercent = Math.Clamp(vp, 0, 100);
                    break;
                case "muted":
                    target.AudioMuted = val == "true" || val == "1";
                    break;
                case "controller_preset":
                    if (int.TryParse(val, NumberStyles.Integer, CultureInfo.InvariantCulture, out var cp))
                        target.ControllerPreset = Math.Clamp(cp, 0, 3);
                    break;
                case "controller_bindings":
                    var cb = StripQuotes(val);
                    if (IsValidBindingsCsv(cb))
                        target.ControllerBindings = cb;
                    break;
                case "keyboard_bindings":
                    var kb = StripQuotes(val);
                    if (IsValidBindingsCsv(kb))
                        target.KeyboardBindings = kb;
                    break;
            }
        }
    }

    private static string StripQuotes(string s)
    {
        if (s.Length >= 2 && s[0] == '"' && s[^1] == '"')
            return s[1..^1];
        return s;
    }

    private static bool IsValidBindingsCsv(string csv)
    {
        var parts = csv.Split(',');
        if (parts.Length != 12)
            return false;
        foreach (var p in parts)
        {
            if (!int.TryParse(p.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out _))
                return false;
        }
        return true;
    }

    public static string Serialize(SkyRuntimeSettings settings)
    {
        var aspect = Math.Clamp(settings.AspectRatio, 0, 3);
        var hud = Math.Clamp(settings.HudLayout, 0, 1);
        var refresh = Math.Clamp(settings.RefreshRate, 0, 4);
        var shader = Math.Clamp(settings.ShaderFilter, 0, 4);
        var volume = Math.Clamp(settings.AudioVolumePercent, 0, 100);
        var preset = Math.Clamp(settings.ControllerPreset, 0, 3);
        var ctrlBindings = IsValidBindingsCsv(settings.ControllerBindings)
            ? settings.ControllerBindings
            : new SkyRuntimeSettings().ControllerBindings;
        var keyBindings = IsValidBindingsCsv(settings.KeyboardBindings)
            ? settings.KeyboardBindings
            : new SkyRuntimeSettings().KeyboardBindings;

        var sb = new StringBuilder();
        sb.Append("[graphics]\n");
        sb.Append($"aspect_ratio = {aspect.ToString(CultureInfo.InvariantCulture)}\n");
        sb.Append($"hud_layout = {hud.ToString(CultureInfo.InvariantCulture)}\n");
        sb.Append($"refresh_rate = {refresh.ToString(CultureInfo.InvariantCulture)}\n");
        sb.Append($"shader_filter = {shader.ToString(CultureInfo.InvariantCulture)}\n");
        sb.Append($"weather_ambient_bloom = {(settings.WeatherAmbientBloom ? "true" : "false")}\n");
        sb.Append($"show_fps_meter = {(settings.ShowFpsMeter ? "true" : "false")}\n\n");
        sb.Append("[audio]\n");
        sb.Append($"volume_percent = {volume.ToString(CultureInfo.InvariantCulture)}\n");
        sb.Append($"muted = {(settings.AudioMuted ? "true" : "false")}\n\n");
        sb.Append("[input]\n");
        sb.Append($"controller_preset = {preset.ToString(CultureInfo.InvariantCulture)}\n");
        sb.Append($"controller_bindings = \"{ctrlBindings}\"\n");
        sb.Append($"keyboard_bindings = \"{keyBindings}\"\n");
        return sb.ToString();
    }

    public static void SaveAtomic(SkyRuntimeSettings settings, string? path = null)
    {
        var targetPath = path ?? RomPreparationService.GetSkySettingsPath();
        var dir = Path.GetDirectoryName(targetPath);
        if (!string.IsNullOrEmpty(dir))
            Directory.CreateDirectory(dir);

        var content = Serialize(settings);
        var tmpPath = Path.Combine(dir ?? ".", $".{Path.GetFileName(targetPath)}.{Guid.NewGuid():N}.tmp");
        try
        {
            File.WriteAllText(tmpPath, content, new UTF8Encoding(false));
            File.Move(tmpPath, targetPath, overwrite: true);
        }
        finally
        {
            if (File.Exists(tmpPath))
                File.Delete(tmpPath);
        }
    }

    public static string FormatSummary(SkyRuntimeSettings settings)
    {
        var ar = AspectRatioLabels[Math.Clamp(settings.AspectRatio, 0, AspectRatioLabels.Length - 1)];
        var hl = HudLayoutLabels[Math.Clamp(settings.HudLayout, 0, HudLayoutLabels.Length - 1)];
        var rr = RefreshRateLabels[Math.Clamp(settings.RefreshRate, 0, RefreshRateLabels.Length - 1)];
        var sf = ShaderFilterLabels[Math.Clamp(settings.ShaderFilter, 0, ShaderFilterLabels.Length - 1)];
        var audio = settings.AudioMuted ? "Muted" : $"{Math.Clamp(settings.AudioVolumePercent, 0, 100)}%";
        return $"{ar} • {hl} • {rr} • {sf} • Audio {audio}";
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using SkyRecompiled.Launcher.Models;

namespace SkyRecompiled.Launcher.Services;

/// <summary>
/// Inspects the 128 KiB (131072-byte) EEPROM save file and provides atomic,
/// safety-backed backup and restore operations.
/// </summary>
public static class SaveManagementService
{
    public const long ExpectedEepromSaveBytes = 131072;

    public static string GetSaveFilePath(string? savesDir = null)
        => Path.Combine(savesDir ?? RomPreparationService.GetSavesDir(), "pmdsky.sav");

    public static string GetBackupsDir(string? savesDir = null)
        => Path.Combine(savesDir ?? RomPreparationService.GetSavesDir(), "backups");

    public static SaveFileInfo InspectSave(string? savesDir = null, string? savestatesDir = null)
    {
        var resolvedSavesDir = savesDir ?? RomPreparationService.GetSavesDir();
        var resolvedStatesDir = savestatesDir ?? RomPreparationService.GetSavestatesDir();
        var savePath = GetSaveFilePath(resolvedSavesDir);

        int savestateCount = 0;
        if (Directory.Exists(resolvedStatesDir))
        {
            savestateCount = Directory.EnumerateFiles(resolvedStatesDir, "*", SearchOption.TopDirectoryOnly)
                .Count(p => !Path.GetFileName(p).StartsWith('.'));
        }

        if (!File.Exists(savePath))
        {
            return new SaveFileInfo(
                savePath,
                Exists: false,
                SizeBytes: 0,
                IsValidEepromSize: false,
                LastModifiedUtc: null,
                Sha256Short: "",
                SavestateCount: savestateCount);
        }

        var fi = new FileInfo(savePath);
        string shaShort = "";
        using (var sha = SHA256.Create())
        using (var stream = File.OpenRead(savePath))
        {
            var hash = sha.ComputeHash(stream);
            shaShort = Convert.ToHexString(hash).ToLowerInvariant()[..16];
        }

        return new SaveFileInfo(
            savePath,
            Exists: true,
            SizeBytes: fi.Length,
            IsValidEepromSize: fi.Length == ExpectedEepromSaveBytes,
            LastModifiedUtc: fi.LastWriteTimeUtc,
            Sha256Short: shaShort,
            SavestateCount: savestateCount);
    }

    public static IReadOnlyList<SaveBackupInfo> ListBackups(string? savesDir = null)
    {
        var backupsDir = GetBackupsDir(savesDir);
        if (!Directory.Exists(backupsDir))
            return Array.Empty<SaveBackupInfo>();

        return Directory.EnumerateFiles(backupsDir, "*.sav", SearchOption.TopDirectoryOnly)
            .Select(p => new FileInfo(p))
            .OrderByDescending(fi => fi.LastWriteTimeUtc)
            .ThenByDescending(fi => fi.Name, StringComparer.Ordinal)
            .Select(fi => new SaveBackupInfo(
                fi.Name,
                fi.FullName,
                fi.Length,
                fi.Length == ExpectedEepromSaveBytes,
                fi.LastWriteTimeUtc))
            .ToList();
    }

    public static SaveBackupInfo CreateBackup(string? savesDir = null, string prefix = "pmdsky")
    {
        var resolvedSavesDir = savesDir ?? RomPreparationService.GetSavesDir();
        var savePath = GetSaveFilePath(resolvedSavesDir);
        if (!File.Exists(savePath))
            throw new FileNotFoundException("No active save file exists to back up.", savePath);

        var backupsDir = GetBackupsDir(resolvedSavesDir);
        Directory.CreateDirectory(backupsDir);

        var safePrefix = string.IsNullOrWhiteSpace(prefix) ? "pmdsky" : prefix.Trim();
        var stamp = DateTimeOffset.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        var candidate = Path.Combine(backupsDir, $"{safePrefix}-{stamp}.sav");
        int suffix = 1;
        while (File.Exists(candidate))
        {
            candidate = Path.Combine(backupsDir, $"{safePrefix}-{stamp}-{suffix}.sav");
            suffix++;
        }

        var data = File.ReadAllBytes(savePath);
        AtomicWriteBytes(candidate, data);

        var fi = new FileInfo(candidate);
        return new SaveBackupInfo(
            fi.Name,
            fi.FullName,
            fi.Length,
            fi.Length == ExpectedEepromSaveBytes,
            fi.LastWriteTimeUtc);
    }

    public static void RestoreBackup(string backupPath, string? savesDir = null)
    {
        if (string.IsNullOrWhiteSpace(backupPath) || !File.Exists(backupPath))
            throw new FileNotFoundException("Selected save backup does not exist.", backupPath);

        var backupBytes = File.ReadAllBytes(backupPath);
        if (backupBytes.LongLength != ExpectedEepromSaveBytes)
        {
            throw new InvalidDataException(
                $"Refusing to restore save backup '{Path.GetFileName(backupPath)}': expected exactly {ExpectedEepromSaveBytes} bytes (128 KiB EEPROM), got {backupBytes.LongLength} bytes.");
        }

        var resolvedSavesDir = savesDir ?? RomPreparationService.GetSavesDir();
        Directory.CreateDirectory(resolvedSavesDir);
        var savePath = GetSaveFilePath(resolvedSavesDir);

        if (File.Exists(savePath))
        {
            CreateBackup(resolvedSavesDir, "pre-restore");
        }

        AtomicWriteBytes(savePath, backupBytes);
    }

    private static void AtomicWriteBytes(string targetPath, byte[] data)
    {
        var dir = Path.GetDirectoryName(targetPath);
        if (!string.IsNullOrEmpty(dir))
            Directory.CreateDirectory(dir);

        var tmpPath = Path.Combine(dir ?? ".", $".{Path.GetFileName(targetPath)}.{Guid.NewGuid():N}.tmp");
        try
        {
            File.WriteAllBytes(tmpPath, data);
            File.Move(tmpPath, targetPath, overwrite: true);
        }
        finally
        {
            if (File.Exists(tmpPath))
                File.Delete(tmpPath);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using SkyRecompiled.Launcher.Models;

namespace SkyRecompiled.Launcher.Services;

/// <summary>
/// Discovers, validates, orders, and persists layered NitroFS mods under <c>mods/</c>
/// with parity to <c>tools/sky_mod_packer.py</c>.
/// </summary>
public static partial class ModManagerService
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [GeneratedRegex("^[A-Za-z0-9_-]+$", RegexOptions.CultureInvariant)]
    private static partial Regex ValidModIdRegex();

    public static bool IsSymlink(FileSystemInfo info)
        => info.LinkTarget != null || (info.Attributes & FileAttributes.ReparsePoint) != 0;

    public static void ValidateVirtualPath(string path)
    {
        if (string.IsNullOrEmpty(path) || path.StartsWith('/') || path.Contains('\\') || path.Contains(':'))
            throw new ArgumentException($"Invalid NitroFS path: '{path}'", nameof(path));

        var parts = path.Split('/');
        foreach (var part in parts)
        {
            if (part is "" or "." or "..")
                throw new ArgumentException($"Invalid NitroFS path: '{path}'", nameof(path));
            if (part.Length > 127)
                throw new ArgumentException($"Invalid NitroFS path component: '{part}'", nameof(path));
            foreach (var ch in part)
            {
                if (ch > 0xFF)
                    throw new ArgumentException($"NitroFS path is not representable in the FNT: '{path}'", nameof(path));
                if (ch < 32)
                    throw new ArgumentException($"Invalid NitroFS path component: '{part}'", nameof(path));
            }
        }
    }

    public static ModScanResult ScanMods(string? modsRoot = null, string? stateFilePath = null)
    {
        var root = modsRoot ?? RomPreparationService.GetModsDir();
        var statePath = stateFilePath ?? RomPreparationService.GetModStatePath();
        var issues = new List<ModValidationIssue>();

        if (!Directory.Exists(root))
        {
            return new ModScanResult(Array.Empty<ModEntry>(), Array.Empty<ModConflict>(), issues);
        }

        var overrides = LoadState(statePath);
        var discovered = new List<ModEntry>();
        var seenIds = new HashSet<string>(StringComparer.Ordinal);

        IEnumerable<string> entryPaths;
        try
        {
            entryPaths = Directory.GetFileSystemEntries(root).OrderBy(p => p, StringComparer.Ordinal);
        }
        catch (Exception ex)
        {
            issues.Add(new ModValidationIssue("(mods)", $"Failed to enumerate mods folder: {ex.Message}"));
            return new ModScanResult(Array.Empty<ModEntry>(), Array.Empty<ModConflict>(), issues);
        }

        foreach (var entryPath in entryPaths)
        {
            var dirInfo = new DirectoryInfo(entryPath);
            if (IsSymlink(dirInfo))
            {
                issues.Add(new ModValidationIssue(dirInfo.Name, "Symlinked mod entries are not allowed."));
                continue;
            }
            if (!dirInfo.Exists)
                continue; // Not a directory

            var romfsPath = Path.Combine(entryPath, "romfs");
            var romfsInfo = new DirectoryInfo(romfsPath);
            if (IsSymlink(romfsInfo))
            {
                issues.Add(new ModValidationIssue(dirInfo.Name, $"Mod romfs must not be a symlink: {romfsPath}"));
                continue;
            }
            if (!romfsInfo.Exists)
            {
                // Ignore directories without romfs/ before validating metadata (matches sky_mod_packer.py)
                continue;
            }

            ParsedModMetadata meta;
            try
            {
                meta = ParseModToml(Path.Combine(entryPath, "mod.toml"), dirInfo.Name);
            }
            catch (Exception ex)
            {
                issues.Add(new ModValidationIssue(dirInfo.Name, ex.Message));
                continue;
            }

            if (string.IsNullOrEmpty(meta.Id) || !ValidModIdRegex().IsMatch(meta.Id))
            {
                issues.Add(new ModValidationIssue(dirInfo.Name, $"Invalid mod ID: '{meta.Id}'"));
                continue;
            }
            if (!seenIds.Add(meta.Id))
            {
                issues.Add(new ModValidationIssue(dirInfo.Name, $"Duplicate mod ID: '{meta.Id}'"));
                continue;
            }

            List<string> virtualPaths;
            try
            {
                virtualPaths = CollectRomfsPaths(romfsPath);
            }
            catch (Exception ex)
            {
                issues.Add(new ModValidationIssue(meta.Id, ex.Message));
                continue;
            }

            bool effectiveEnabled = meta.Enabled;
            int effectivePriority = meta.Priority;
            if (overrides.TryGetValue(meta.Id, out var ov))
            {
                effectiveEnabled = ov.Enabled;
                effectivePriority = ov.Priority;
            }

            discovered.Add(new ModEntry(
                Id: meta.Id,
                Name: string.IsNullOrWhiteSpace(meta.Name) ? meta.Id : meta.Name,
                Author: meta.Author,
                Version: string.IsNullOrWhiteSpace(meta.Version) ? "1.0.0" : meta.Version,
                Priority: effectivePriority,
                DefaultPriority: meta.Priority,
                Description: meta.Description,
                Enabled: effectiveEnabled,
                DefaultEnabled: meta.Enabled,
                FolderPath: entryPath,
                FileCount: virtualPaths.Count,
                VirtualPaths: virtualPaths));
        }

        // Deterministic load order: priority ascending, then id ascending (higher priority applies last / wins)
        discovered.Sort((a, b) =>
        {
            var cmp = a.Priority.CompareTo(b.Priority);
            return cmp != 0 ? cmp : string.Compare(a.Id, b.Id, StringComparison.Ordinal);
        });

        var touchHistory = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        foreach (var mod in discovered)
        {
            if (!mod.Enabled) continue;
            foreach (var vpath in mod.VirtualPaths)
            {
                if (!touchHistory.TryGetValue(vpath, out var chain))
                {
                    chain = new List<string>();
                    touchHistory[vpath] = chain;
                }
                chain.Add(mod.Id);
            }
        }

        var conflicts = touchHistory
            .Where(kv => kv.Value.Count > 1)
            .OrderBy(kv => kv.Key, StringComparer.Ordinal)
            .Select(kv => new ModConflict(kv.Key, kv.Value.ToArray(), kv.Value[^1]))
            .ToList();

        return new ModScanResult(discovered, conflicts, issues);
    }

    private static List<string> CollectRomfsPaths(string romfsRoot)
    {
        var collected = new List<string>();
        var pending = new Stack<string>();
        pending.Push(romfsRoot);

        while (pending.Count > 0)
        {
            var cur = pending.Pop();
            foreach (var subDir in Directory.GetDirectories(cur).OrderBy(p => p, StringComparer.Ordinal))
            {
                var di = new DirectoryInfo(subDir);
                if (IsSymlink(di))
                    throw new InvalidOperationException($"Symlinks are not allowed in mod layers: {subDir}");
                pending.Push(subDir);
            }

            foreach (var file in Directory.GetFiles(cur).OrderBy(p => p, StringComparer.Ordinal))
            {
                var fi = new FileInfo(file);
                if (IsSymlink(fi))
                    throw new InvalidOperationException($"Symlinks are not allowed in mod layers: {file}");

                var rel = Path.GetRelativePath(romfsRoot, file).Replace('\\', '/');
                ValidateVirtualPath(rel);
                collected.Add(rel);
            }
        }

        collected.Sort(StringComparer.Ordinal);
        return collected;
    }

    public sealed record ParsedModMetadata(
        string Id,
        string Name,
        string Author,
        string Version,
        int Priority,
        string Description,
        bool Enabled);

    public static ParsedModMetadata ParseModToml(string tomlPath, string defaultId)
    {
        string id = defaultId;
        string name = "";
        string author = "";
        string version = "1.0.0";
        int priority = 100;
        string description = "";
        bool enabled = true;

        if (!File.Exists(tomlPath))
            return new ParsedModMetadata(id, name, author, version, priority, description, enabled);

        var text = File.ReadAllText(tomlPath, Encoding.UTF8);
        foreach (var rawLine in text.Split('\n'))
        {
            var stripped = StripTomlComment(rawLine).Trim();
            if (string.IsNullOrEmpty(stripped) || stripped.StartsWith('['))
                continue;

            var eq = stripped.IndexOf('=');
            if (eq < 0)
                throw new FormatException($"Invalid mod.toml line in {tomlPath}: '{stripped}'");

            var key = stripped[..eq].Trim();
            var rawVal = stripped[(eq + 1)..].Trim();

            switch (key)
            {
                case "id":
                    id = UnquoteTomlString(rawVal, tomlPath, key);
                    break;
                case "name":
                    name = UnquoteTomlString(rawVal, tomlPath, key);
                    break;
                case "author":
                    author = UnquoteTomlString(rawVal, tomlPath, key);
                    break;
                case "version":
                    version = UnquoteTomlString(rawVal, tomlPath, key);
                    break;
                case "description":
                    description = UnquoteTomlString(rawVal, tomlPath, key);
                    break;
                case "priority":
                    priority = ParseTomlInt(rawVal, tomlPath);
                    break;
                case "enabled":
                    enabled = ParseTomlBool(rawVal, tomlPath);
                    break;
            }
        }

        return new ParsedModMetadata(id, name, author, version, priority, description, enabled);
    }

    private static string StripTomlComment(string line)
    {
        bool inDouble = false;
        bool inSingle = false;
        for (int i = 0; i < line.Length; i++)
        {
            char c = line[i];
            if (c == '\\' && inDouble && i + 1 < line.Length)
            {
                i++;
                continue;
            }
            if (c == '"' && !inSingle)
                inDouble = !inDouble;
            else if (c == '\'' && !inDouble)
                inSingle = !inSingle;
            else if (c == '#' && !inDouble && !inSingle)
                return line[..i];
        }
        return line;
    }

    private static string UnquoteTomlString(string rawVal, string tomlPath, string key)
    {
        if (rawVal.Length >= 2 && rawVal[0] == '"' && rawVal[^1] == '"')
        {
            return rawVal[1..^1]
                .Replace("\\\"", "\"")
                .Replace("\\\\", "\\")
                .Replace("\\n", "\n")
                .Replace("\\t", "\t");
        }
        if (rawVal.Length >= 2 && rawVal[0] == '\'' && rawVal[^1] == '\'')
        {
            return rawVal[1..^1];
        }
        throw new FormatException($"Invalid string value for '{key}' in {tomlPath}: '{rawVal}'");
    }

    private static int ParseTomlInt(string rawVal, string tomlPath)
    {
        if (string.Equals(rawVal, "true", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(rawVal, "false", StringComparison.OrdinalIgnoreCase))
            throw new FormatException($"Invalid mod priority in {tomlPath}: {rawVal}");

        var unquoted = rawVal;
        if (rawVal.Length >= 2 && ((rawVal[0] == '"' && rawVal[^1] == '"') || (rawVal[0] == '\'' && rawVal[^1] == '\'')))
            unquoted = rawVal[1..^1].Trim();

        if (!int.TryParse(unquoted, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed))
            throw new FormatException($"Invalid mod priority in {tomlPath}: {rawVal}");
        return parsed;
    }

    private static bool ParseTomlBool(string rawVal, string tomlPath)
    {
        var unquoted = rawVal;
        if (rawVal.Length >= 2 && ((rawVal[0] == '"' && rawVal[^1] == '"') || (rawVal[0] == '\'' && rawVal[^1] == '\'')))
            unquoted = rawVal[1..^1].Trim();

        if (string.Equals(unquoted, "true", StringComparison.OrdinalIgnoreCase))
            return true;
        if (string.Equals(unquoted, "false", StringComparison.OrdinalIgnoreCase))
            return false;
        throw new FormatException($"Invalid mod enabled flag in {tomlPath}: {rawVal}");
    }

    public static Dictionary<string, ModStateOverride> LoadState(string? stateFilePath = null)
    {
        var path = stateFilePath ?? RomPreparationService.GetModStatePath();
        if (!File.Exists(path))
            return new Dictionary<string, ModStateOverride>(StringComparer.Ordinal);

        try
        {
            var json = File.ReadAllText(path, Encoding.UTF8);
            var parsed = JsonSerializer.Deserialize<Dictionary<string, ModStateOverride>>(json);
            return parsed != null
                ? new Dictionary<string, ModStateOverride>(parsed, StringComparer.Ordinal)
                : new Dictionary<string, ModStateOverride>(StringComparer.Ordinal);
        }
        catch
        {
            return new Dictionary<string, ModStateOverride>(StringComparer.Ordinal);
        }
    }

    public static void SaveStateAtomic(IDictionary<string, ModStateOverride> overrides, string? stateFilePath = null)
    {
        var path = stateFilePath ?? RomPreparationService.GetModStatePath();
        var sorted = new SortedDictionary<string, ModStateOverride>(overrides, StringComparer.Ordinal);
        var json = JsonSerializer.Serialize(sorted, JsonOptions) + "\n";
        AtomicWriteText(path, json);
    }

    public static void ExportActiveModsManifest(ModScanResult scan, string? manifestPath = null)
    {
        var path = manifestPath ?? RomPreparationService.GetActiveModsManifestPath();
        var payload = new
        {
            version = 1,
            updated_utc = DateTimeOffset.UtcNow.ToString("O"),
            enabled_mods = scan.Mods
                .Where(m => m.Enabled)
                .Select(m => new
                {
                    id = m.Id,
                    name = m.Name,
                    priority = m.Priority,
                    folder = m.FolderPath,
                    file_count = m.FileCount,
                })
                .ToArray(),
            conflicts = scan.Conflicts
                .Select(c => new
                {
                    path = c.VirtualPath,
                    chain = c.ModChain,
                    winner = c.WinnerModId,
                })
                .ToArray(),
        };
        var json = JsonSerializer.Serialize(payload, JsonOptions) + "\n";
        AtomicWriteText(path, json);
    }

    public static ModEntry ImportModFolder(string sourceDir, string? modsRoot = null, string? stateFilePath = null)
    {
        if (string.IsNullOrWhiteSpace(sourceDir))
            throw new ArgumentException("Source mod folder path is required.", nameof(sourceDir));

        var srcInfo = new DirectoryInfo(sourceDir);
        if (!srcInfo.Exists)
            throw new DirectoryNotFoundException($"Mod folder does not exist: {sourceDir}");
        if (IsSymlink(srcInfo))
            throw new InvalidOperationException("Cannot import a symlinked mod folder.");

        var srcRomfs = Path.Combine(sourceDir, "romfs");
        var srcRomfsInfo = new DirectoryInfo(srcRomfs);
        if (!srcRomfsInfo.Exists)
            throw new InvalidOperationException($"Selected folder '{srcInfo.Name}' does not contain a 'romfs' directory.");
        if (IsSymlink(srcRomfsInfo))
            throw new InvalidOperationException("Source mod 'romfs' directory must not be a symlink.");

        var meta = ParseModToml(Path.Combine(sourceDir, "mod.toml"), srcInfo.Name);
        if (string.IsNullOrEmpty(meta.Id) || !ValidModIdRegex().IsMatch(meta.Id))
            throw new InvalidOperationException($"Invalid mod ID '{meta.Id}'. Allowed characters: A-Z, a-z, 0-9, _, -.");

        _ = CollectRomfsPaths(srcRomfs);

        var root = modsRoot ?? RomPreparationService.GetModsDir();
        Directory.CreateDirectory(root);

        var existing = ScanMods(root, stateFilePath);
        if (existing.Mods.Any(m => string.Equals(m.Id, meta.Id, StringComparison.Ordinal)))
            throw new InvalidOperationException($"A mod with ID '{meta.Id}' is already installed.");

        var targetFolderName = ValidModIdRegex().IsMatch(srcInfo.Name) ? srcInfo.Name : meta.Id;
        var destDir = Path.Combine(root, targetFolderName);
        if (Directory.Exists(destDir))
            throw new InvalidOperationException($"Destination folder '{targetFolderName}' already exists in mods/.");

        CopyDirectoryClean(sourceDir, destDir);

        var refreshed = ScanMods(root, stateFilePath);
        return refreshed.Mods.First(m => string.Equals(m.Id, meta.Id, StringComparison.Ordinal));
    }

    private static void CopyDirectoryClean(string sourceDir, string destDir)
    {
        Directory.CreateDirectory(destDir);
        foreach (var file in Directory.GetFiles(sourceDir))
        {
            var fi = new FileInfo(file);
            if (IsSymlink(fi))
                throw new InvalidOperationException($"Refusing to copy symlinked file: {file}");
            File.Copy(file, Path.Combine(destDir, fi.Name), overwrite: false);
        }

        foreach (var subDir in Directory.GetDirectories(sourceDir))
        {
            var di = new DirectoryInfo(subDir);
            if (IsSymlink(di))
                throw new InvalidOperationException($"Refusing to copy symlinked directory: {subDir}");
            CopyDirectoryClean(subDir, Path.Combine(destDir, di.Name));
        }
    }

    private static void AtomicWriteText(string targetPath, string content)
    {
        var dir = Path.GetDirectoryName(targetPath);
        if (!string.IsNullOrEmpty(dir))
            Directory.CreateDirectory(dir);

        var tmpPath = Path.Combine(dir ?? ".", $".{Path.GetFileName(targetPath)}.{Guid.NewGuid():N}.tmp");
        try
        {
            File.WriteAllText(tmpPath, content, new UTF8Encoding(false));
            File.Move(tmpPath, targetPath, overwrite: true);
        }
        finally
        {
            if (File.Exists(tmpPath))
                File.Delete(tmpPath);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Text;
using SkyRecompiled.Launcher.Models;

namespace SkyRecompiled.Launcher.Services;

/// <summary>
/// Bitstream encoder/decoder and checksum verifier for 34-character Wonder Mail S
/// and 54-character Friend Rescue SOS / A-OK / Thank-You passwords, matching
/// <c>tools/wondermail.py</c> and <c>services/rescue-worker/src/index.ts</c>.
/// </summary>
public static class WonderMailCodec
{
    public const string WonderMailCharset = "&67NPR89F0+#STXY45MCHJ-K12=%3Q@W";

    public static readonly int[] BitsSwap =
    {
        7, 27, 13, 31, 21, 26, 6, 1, 23, 28, 9, 30, 10, 32, 16, 33,
        15, 8, 29, 17, 20, 0, 19, 22, 5, 18, 14, 4, 3, 24, 2, 11, 12, 25,
    };

    private static readonly Dictionary<char, int> CharToVal = BuildCharMap();
    private static readonly uint[] Crc32Table = BuildCrc32Table();

    private static Dictionary<char, int> BuildCharMap()
    {
        var map = new Dictionary<char, int>(WonderMailCharset.Length);
        for (int i = 0; i < WonderMailCharset.Length; i++)
            map[WonderMailCharset[i]] = i;
        return map;
    }

    private static uint[] BuildCrc32Table()
    {
        var table = new uint[256];
        for (uint i = 0; i < 256; i++)
        {
            uint c = i;
            for (int k = 0; k < 8; k++)
                c = (c & 1) != 0 ? (0xEDB88320u ^ (c >> 1)) : (c >> 1);
            table[i] = c;
        }
        return table;
    }

    public static uint ComputeCrc32(ReadOnlySpan<byte> data)
    {
        uint crc = 0xFFFFFFFFu;
        foreach (byte b in data)
            crc = Crc32Table[(crc ^ b) & 0xFF] ^ (crc >> 8);
        return crc ^ 0xFFFFFFFFu;
    }

    public static int ComputeFletcherChecksum(ReadOnlySpan<int> symbols)
    {
        int c1 = 0;
        int c2 = 0;
        foreach (int s in symbols)
        {
            c1 = (c1 + s) & 0x1F;
            c2 = (c2 + c1) & 0x1F;
        }
        return (c1 << 5) | c2;
    }

    public static string NormalizeAndValidatePassword(string raw, int expectedLen, string label = "Password")
    {
        if (raw == null)
            throw new ArgumentException($"Invalid {label} length: expected {expectedLen} chars, got 0", nameof(raw));

        var sb = new StringBuilder(raw.Length);
        foreach (char ch in raw)
        {
            if (!char.IsWhiteSpace(ch))
                sb.Append(char.ToUpperInvariant(ch));
        }

        var cleaned = sb.ToString();
        for (int i = 0; i < cleaned.Length; i++)
        {
            if (!CharToVal.ContainsKey(cleaned[i]))
                throw new FormatException($"Invalid {label} character '{cleaned[i]}' at position {i}");
        }

        if (cleaned.Length != expectedLen)
            throw new FormatException($"Invalid {label} length: expected {expectedLen} chars, got {cleaned.Length}");

        return cleaned;
    }

    public static string FormatMultiline(string password, int lineLen = 17)
    {
        if (string.IsNullOrEmpty(password) || lineLen <= 0)
            return password ?? string.Empty;

        var lines = new List<string>();
        for (int i = 0; i < password.Length; i += lineLen)
        {
            int take = Math.Min(lineLen, password.Length - i);
            lines.Add(password.Substring(i, take));
        }
        return string.Join(Environment.NewLine, lines);
    }

    public static string EncodeWonderMailS(MissionData mission)
    {
        var bw = new BitWriter();
        bw.WriteBits((uint)(mission.Type & 0xF), 4);
        bw.WriteBits((uint)(mission.Subtype & 0xF), 4);
        bw.WriteBits((uint)(mission.DungeonId & 0x7F), 7);
        bw.WriteBits((uint)(mission.Floor & 0x7F), 7);
        bw.WriteBits((uint)(mission.ClientId & 0x7FF), 11);
        bw.WriteBits((uint)(mission.TargetId & 0x7FF), 11);
        bw.WriteBits((uint)(mission.ItemWanted & 0x7FF), 11);
        bw.WriteBits((uint)(mission.RewardType & 0xF), 4);
        bw.WriteBits((uint)(mission.ItemReward & 0x7FF), 11);
        bw.WriteBits((uint)(mission.RestrictionType & 0xF), 4);
        bw.WriteBits((uint)(mission.Restriction & 0x7FF), 11);

        while (bw.BitCount < 136)
            bw.WriteBit(0);

        var payloadBytes = bw.ToBytes(17);
        uint crc = ComputeCrc32(payloadBytes);

        bw.WriteBits(crc, 32);
        bw.WriteBits(0, 2);

        var rawSymbols = bw.To5BitSymbols();
        var scrambled = new int[34];
        for (int i = 0; i < 34; i++)
            scrambled[BitsSwap[i]] = rawSymbols[i];

        var chars = new char[34];
        for (int i = 0; i < 34; i++)
            chars[i] = WonderMailCharset[scrambled[i]];
        return new string(chars);
    }

    public static MissionData DecodeWonderMailS(string password)
    {
        var clean = NormalizeAndValidatePassword(password, 34, "Wonder Mail S password");

        var scrambled = new int[34];
        for (int i = 0; i < 34; i++)
            scrambled[i] = CharToVal[clean[i]];

        var unscrambled = new int[34];
        for (int i = 0; i < 34; i++)
            unscrambled[i] = scrambled[BitsSwap[i]];

        var bits = new List<int>(170);
        foreach (int sym in unscrambled)
        {
            for (int b = 4; b >= 0; b--)
                bits.Add((sym >> b) & 1);
        }

        var payloadBytes = new byte[17];
        for (int byteIdx = 0; byteIdx < 17; byteIdx++)
        {
            byte val = 0;
            int bitBase = byteIdx * 8;
            for (int b = 0; b < 8; b++)
                val = (byte)((val << 1) | bits[bitBase + b]);
            payloadBytes[byteIdx] = val;
        }

        uint expectedCrc = 0;
        for (int i = 136; i < 168; i++)
            expectedCrc = (expectedCrc << 1) | (uint)bits[i];

        uint actualCrc = ComputeCrc32(payloadBytes);
        if (actualCrc != expectedCrc)
            throw new FormatException("Invalid Wonder Mail S checksum (CRC32 mismatch)");

        var br = new BitReader(bits, 136);
        return new MissionData
        {
            Type = (int)br.ReadBits(4),
            Subtype = (int)br.ReadBits(4),
            DungeonId = (int)br.ReadBits(7),
            Floor = (int)br.ReadBits(7),
            ClientId = (int)br.ReadBits(11),
            TargetId = (int)br.ReadBits(11),
            ItemWanted = (int)br.ReadBits(11),
            RewardType = (int)br.ReadBits(4),
            ItemReward = (int)br.ReadBits(11),
            RestrictionType = (int)br.ReadBits(4),
            Restriction = (int)br.ReadBits(11),
        };
    }

    public static string EncodeRescueMail(RescueMailData data)
    {
        var kindUpper = (data.Kind ?? string.Empty).ToUpperInvariant();
        int kindCode = kindUpper switch
        {
            "SOS" => 1,
            "A-OK" => 2,
            "THANK-YOU" => 3,
            _ => throw new ArgumentException($"Invalid Rescue Mail kind: '{data.Kind}'", nameof(data)),
        };

        if (data.DungeonId < 0 || data.DungeonId > 0x7F)
            throw new ArgumentOutOfRangeException(nameof(data), $"dungeon_id out of range [0..127]: {data.DungeonId}");
        if (data.Floor < 0 || data.Floor > 0x7F)
            throw new ArgumentOutOfRangeException(nameof(data), $"floor out of range [0..127]: {data.Floor}");
        if (data.ClientSpecies < 0 || data.ClientSpecies > 0x7FF)
            throw new ArgumentOutOfRangeException(nameof(data), $"client_species out of range [0..2047]: {data.ClientSpecies}");
        if (data.RevivesLeft < 0 || data.RevivesLeft > 0x7)
            throw new ArgumentOutOfRangeException(nameof(data), $"revives_left out of range [0..7]: {data.RevivesLeft}");

        var bw = new BitWriter();
        bw.WriteBits((uint)kindCode, 3);
        bw.WriteBits((uint)data.DungeonId, 7);
        bw.WriteBits((uint)data.Floor, 7);
        bw.WriteBits((uint)data.ClientSpecies, 11);
        bw.WriteBits(data.RescueId, 32);
        bw.WriteBits((uint)data.RevivesLeft, 3);

        var nameBytes = ToLatin1BytesWithReplacement(data.TeamName ?? string.Empty);
        int nameLen = Math.Min(10, nameBytes.Length);
        bw.WriteBits((uint)nameLen, 4);
        for (int i = 0; i < nameLen; i++)
            bw.WriteBits(nameBytes[i], 8);

        var rawSymbols = bw.To5BitSymbols();
        while (rawSymbols.Count < 52)
            rawSymbols.Add((rawSymbols.Count * 7) % 32);

        var chk = ComputeFletcherChecksum(rawSymbols.GetRange(0, 52).ToArray());
        rawSymbols.Add((chk >> 5) & 0x1F);
        rawSymbols.Add(chk & 0x1F);

        var chars = new char[54];
        for (int i = 0; i < 54; i++)
            chars[i] = WonderMailCharset[rawSymbols[i]];
        return new string(chars);
    }

    public static RescueMailData DecodeRescueMail(string password)
    {
        var clean = NormalizeAndValidatePassword(password, 54, "Rescue password");

        var symbols = new int[54];
        for (int i = 0; i < 54; i++)
            symbols[i] = CharToVal[clean[i]];

        int expectedChk = (symbols[52] << 5) | symbols[53];
        int actualChk = ComputeFletcherChecksum(symbols.AsSpan(0, 52));
        if (actualChk != expectedChk)
            throw new FormatException("Invalid Rescue Mail checksum");

        var bits = new List<int>(260);
        for (int i = 0; i < 52; i++)
        {
            for (int b = 4; b >= 0; b--)
                bits.Add((symbols[i] >> b) & 1);
        }

        var br = new BitReader(bits, bits.Count);
        int kindCode = (int)br.ReadBits(3);
        string kindStr = kindCode switch
        {
            1 => "SOS",
            2 => "A-OK",
            3 => "THANK-YOU",
            _ => throw new FormatException($"Invalid Rescue Mail kind code: {kindCode}"),
        };

        int dungeonId = (int)br.ReadBits(7);
        int floor = (int)br.ReadBits(7);
        int clientSpecies = (int)br.ReadBits(11);
        uint rescueId = br.ReadBits(32);
        int revivesLeft = (int)br.ReadBits(3);

        int nameLen = (int)br.ReadBits(4);
        if (nameLen > 10)
            throw new FormatException($"Invalid Rescue Mail team name length: {nameLen}");

        var nameBytes = new byte[nameLen];
        for (int i = 0; i < nameLen; i++)
            nameBytes[i] = (byte)br.ReadBits(8);

        string teamName = Encoding.Latin1.GetString(nameBytes);
        return new RescueMailData
        {
            Kind = kindStr,
            DungeonId = dungeonId,
            Floor = floor,
            TeamName = teamName,
            ClientSpecies = clientSpecies,
            RescueId = rescueId,
            RevivesLeft = revivesLeft,
        };
    }

    public static RescueMailData CreateAokFromSos(RescueMailData sos, string? rescuerTeam = null)
    {
        if (!string.Equals(sos.Kind, "SOS", StringComparison.OrdinalIgnoreCase))
            throw new ArgumentException($"Expected SOS mail, got '{sos.Kind}'", nameof(sos));
        if (sos.RevivesLeft <= 0)
            throw new InvalidOperationException("Cannot create A-OK mail: no revives left");

        var team = string.IsNullOrEmpty(rescuerTeam) ? sos.TeamName : rescuerTeam;
        if (team.Length > 10)
            team = team[..10];

        return new RescueMailData
        {
            Kind = "A-OK",
            DungeonId = sos.DungeonId,
            Floor = sos.Floor,
            TeamName = team,
            ClientSpecies = sos.ClientSpecies,
            RescueId = sos.RescueId,
            RevivesLeft = sos.RevivesLeft - 1,
        };
    }

    public static RescueMailData CreateThankYouFromAok(RescueMailData aok, string? teamName = null)
    {
        if (!string.Equals(aok.Kind, "A-OK", StringComparison.OrdinalIgnoreCase))
            throw new ArgumentException($"Expected A-OK mail, got '{aok.Kind}'", nameof(aok));

        var team = string.IsNullOrEmpty(teamName) ? aok.TeamName : teamName;
        if (team.Length > 10)
            team = team[..10];

        return new RescueMailData
        {
            Kind = "THANK-YOU",
            DungeonId = aok.DungeonId,
            Floor = aok.Floor,
            TeamName = team,
            ClientSpecies = aok.ClientSpecies,
            RescueId = aok.RescueId,
            RevivesLeft = aok.RevivesLeft,
        };
    }

    public static bool VerifyRescueLinkage(RescueMailData earlier, RescueMailData later)
    {
        var eKind = earlier.Kind.ToUpperInvariant();
        var lKind = later.Kind.ToUpperInvariant();
        bool validStep = (eKind == "SOS" && lKind == "A-OK") || (eKind == "A-OK" && lKind == "THANK-YOU");
        if (!validStep)
            return false;

        return earlier.DungeonId == later.DungeonId
            && earlier.Floor == later.Floor
            && earlier.ClientSpecies == later.ClientSpecies
            && earlier.RescueId == later.RescueId;
    }

    private static byte[] ToLatin1BytesWithReplacement(string value)
    {
        var bytes = new byte[value.Length];
        for (int i = 0; i < value.Length; i++)
        {
            char ch = value[i];
            bytes[i] = ch <= 0xFF ? (byte)ch : (byte)'?';
        }
        return bytes;
    }

    private sealed class BitWriter
    {
        private readonly List<int> _bits = new();
        public int BitCount => _bits.Count;

        public void WriteBit(int bit) => _bits.Add(bit & 1);

        public void WriteBits(uint value, int numBits)
        {
            for (int i = numBits - 1; i >= 0; i--)
                _bits.Add((int)((value >> i) & 1u));
        }

        public byte[] ToBytes(int maxBytes)
        {
            int count = Math.Min(maxBytes, (_bits.Count + 7) / 8);
            var result = new byte[count];
            for (int b = 0; b < count; b++)
            {
                int start = b * 8;
                int len = Math.Min(8, _bits.Count - start);
                int val = 0;
                for (int i = 0; i < len; i++)
                    val = (val << 1) | _bits[start + i];
                val <<= (8 - len);
                result[b] = (byte)val;
            }
            return result;
        }

        public List<int> To5BitSymbols()
        {
            var symbols = new List<int>((_bits.Count + 4) / 5);
            for (int start = 0; start < _bits.Count; start += 5)
            {
                int len = Math.Min(5, _bits.Count - start);
                int val = 0;
                for (int i = 0; i < len; i++)
                    val = (val << 1) | _bits[start + i];
                val <<= (5 - len);
                symbols.Add(val);
            }
            return symbols;
        }
    }

    private sealed class BitReader
    {
        private readonly List<int> _bits;
        private readonly int _limit;
        private int _pos;

        public BitReader(List<int> bits, int limit)
        {
            _bits = bits;
            _limit = Math.Min(limit, bits.Count);
        }

        public uint ReadBits(int numBits)
        {
            if (_pos + numBits > _limit)
                throw new FormatException("Unexpected end of bitstream");
            uint val = 0;
            for (int i = 0; i < numBits; i++)
                val = (val << 1) | (uint)_bits[_pos++];
            return val;
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using SkyRecompiled.Launcher.Models;

namespace SkyRecompiled.Launcher.Services;

/// <summary>
/// HTTP client and local token store for the SkyRecompiled Online Friend Rescue
/// Board (<c>services/rescue-worker</c>).
/// </summary>
public sealed class RescueBoardService : IDisposable
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    private readonly string _baseUrl;
    private readonly string _tokenStorePath;
    private readonly bool _offlineMode;
    private readonly HttpClient _http;
    private readonly bool _ownsClient;

    public RescueBoardService(
        string baseUrl,
        string tokenStorePath,
        bool offlineMode = false,
        HttpMessageHandler? handler = null)
    {
        _baseUrl = LauncherPreferences.NormalizeEndpoint(baseUrl);
        _tokenStorePath = tokenStorePath;
        _offlineMode = offlineMode;
        if (handler != null)
        {
            _http = new HttpClient(handler, disposeHandler: false) { Timeout = TimeSpan.FromSeconds(10) };
            _ownsClient = true;
        }
        else
        {
            _http = new HttpClient { Timeout = TimeSpan.FromSeconds(10) };
            _ownsClient = true;
        }
    }

    public bool OfflineMode => _offlineMode;
    public string BaseUrl => _baseUrl;

    public void Dispose()
    {
        if (_ownsClient)
            _http.Dispose();
    }

    public Dictionary<string, RescueTokenEntry> LoadTokens()
    {
        if (!File.Exists(_tokenStorePath))
            return new Dictionary<string, RescueTokenEntry>(StringComparer.Ordinal);
        try
        {
            var json = File.ReadAllText(_tokenStorePath, Encoding.UTF8);
            var dict = JsonSerializer.Deserialize<Dictionary<string, RescueTokenEntry>>(json);
            return dict != null
                ? new Dictionary<string, RescueTokenEntry>(dict, StringComparer.Ordinal)
                : new Dictionary<string, RescueTokenEntry>(StringComparer.Ordinal);
        }
        catch
        {
            return new Dictionary<string, RescueTokenEntry>(StringComparer.Ordinal);
        }
    }

    private void SaveTokensAtomic(Dictionary<string, RescueTokenEntry> tokens)
    {
        var dir = Path.GetDirectoryName(_tokenStorePath);
        if (!string.IsNullOrEmpty(dir))
            Directory.CreateDirectory(dir);

        var sorted = new SortedDictionary<string, RescueTokenEntry>(tokens, StringComparer.Ordinal);
        var json = JsonSerializer.Serialize(sorted, JsonOptions) + "\n";
        var tmpPath = Path.Combine(dir ?? ".", $".{Path.GetFileName(_tokenStorePath)}.{Guid.NewGuid():N}.tmp");
        try
        {
            File.WriteAllText(tmpPath, json, new UTF8Encoding(false));
            File.Move(tmpPath, _tokenStorePath, overwrite: true);
        }
        finally
        {
            if (File.Exists(tmpPath))
                File.Delete(tmpPath);
        }
    }

    private void UpsertToken(string boardId, string? ownerToken, string? claimToken, uint rescueId)
    {
        var tokens = LoadTokens();
        tokens.TryGetValue(boardId, out var existing);
        tokens[boardId] = new RescueTokenEntry(
            OwnerToken: ownerToken ?? existing?.OwnerToken,
            ClaimToken: claimToken ?? existing?.ClaimToken,
            RescueId: rescueId != 0 ? rescueId : (existing?.RescueId ?? 0),
            UpdatedAtUtc: DateTimeOffset.UtcNow);
        SaveTokensAtomic(tokens);
    }

    private static RescueApiResult<T> OfflineBlocked<T>()
        => new(false, default, "Offline mode is enabled in Settings. Disable offline mode to connect to the Pelipper Board.");

    public async Task<RescueApiResult<RescueHealthResult>> CheckHealthAsync(CancellationToken ct = default)
    {
        if (_offlineMode)
            return OfflineBlocked<RescueHealthResult>();

        try
        {
            using var resp = await _http.GetAsync($"{_baseUrl}/health", ct);
            var body = await resp.Content.ReadAsStringAsync(ct);
            if (!resp.IsSuccessStatusCode)
                return new RescueApiResult<RescueHealthResult>(false, default, ExtractError(body, (int)resp.StatusCode), (int)resp.StatusCode);

            using var doc = JsonDocument.Parse(body);
            var root = doc.RootElement;
            var status = root.TryGetProperty("status", out var s) ? (s.GetString() ?? "unknown") : "unknown";
            var service = root.TryGetProperty("service", out var sv) ? (sv.GetString() ?? "SkyRecompiled") : "SkyRecompiled";
            long ts = root.TryGetProperty("timestamp", out var t) && t.TryGetInt64(out var tv) ? tv : 0;
            return new RescueApiResult<RescueHealthResult>(true, new RescueHealthResult(status, service, ts), "Connected", (int)resp.StatusCode);
        }
        catch (Exception ex)
        {
            return new RescueApiResult<RescueHealthResult>(false, default, $"Network error: {ex.Message}");
        }
    }

    public async Task<RescueApiResult<IReadOnlyList<RescueBoardItem>>> ListRescuesAsync(
        string status = "open",
        int? dungeonId = null,
        int limit = 50,
        CancellationToken ct = default)
    {
        if (_offlineMode)
            return OfflineBlocked<IReadOnlyList<RescueBoardItem>>();

        var query = new List<string>
        {
            $"status={Uri.EscapeDataString(status)}",
            $"limit={Math.Clamp(limit, 1, 100)}",
        };
        if (dungeonId.HasValue)
            query.Add($"dungeon_id={dungeonId.Value}");

        var url = $"{_baseUrl}/v1/rescues?{string.Join("&", query)}";
        try
        {
            using var resp = await _http.GetAsync(url, ct);
            var body = await resp.Content.ReadAsStringAsync(ct);
            if (!resp.IsSuccessStatusCode)
                return new RescueApiResult<IReadOnlyList<RescueBoardItem>>(false, default, ExtractError(body, (int)resp.StatusCode), (int)resp.StatusCode);

            using var doc = JsonDocument.Parse(body);
            var list = new List<RescueBoardItem>();
            if (doc.RootElement.TryGetProperty("rescues", out var arr) && arr.ValueKind == JsonValueKind.Array)
            {
                foreach (var el in arr.EnumerateArray())
                    list.Add(ParseRescueItem(el));
            }
            return new RescueApiResult<IReadOnlyList<RescueBoardItem>>(true, list, $"Loaded {list.Count} rescue(s).", (int)resp.StatusCode);
        }
        catch (Exception ex)
        {
            return new RescueApiResult<IReadOnlyList<RescueBoardItem>>(false, default, $"Failed to fetch rescues: {ex.Message}");
        }
    }

    public async Task<RescueApiResult<string>> PostSosRescueAsync(string sosPassword, CancellationToken ct = default)
    {
        RescueMailData decoded;
        try
        {
            decoded = WonderMailCodec.DecodeRescueMail(sosPassword);
        }
        catch (Exception ex)
        {
            return new RescueApiResult<string>(false, null, ex.Message);
        }

        if (!string.Equals(decoded.Kind, "SOS", StringComparison.Ordinal))
            return new RescueApiResult<string>(false, null, $"Expected an SOS password, but decoded kind '{decoded.Kind}'.");

        if (_offlineMode)
            return OfflineBlocked<string>();

        var REDACTED = WonderMailCodec.NormalizeAndValidatePassword(sosPassword, 54, "SOS password");
        var payload = JsonSerializer.Serialize(new
        {
            dungeon_id = decoded.DungeonId,
            floor = decoded.Floor,
            team_name = decoded.TeamName,
            client_species = decoded.ClientSpecies,
            sos_password = REDACTED,
        });

        try
        {
            using var content = new StringContent(payload, Encoding.UTF8, "application/json");
            using var resp = await _http.PostAsync($"{_baseUrl}/v1/rescues", content, ct);
            var body = await resp.Content.ReadAsStringAsync(ct);
            if (!resp.IsSuccessStatusCode)
                return new RescueApiResult<string>(false, null, ExtractError(body, (int)resp.StatusCode), (int)resp.StatusCode);

            using var doc = JsonDocument.Parse(body);
            var root = doc.RootElement;
            var id = root.GetProperty("id").GetString() ?? "";
            var ownerToken = REDACTED, out var ot) ? ot.GetString() : null;
            uint rescueId = root.TryGetProperty("rescue_id", out var rid) && rid.TryGetUInt32(out var rval)
                ? rval
                : decoded.RescueId;

            if (!string.IsNullOrEmpty(id) && !string.IsNullOrEmpty(ownerToken))
                UpsertToken(id, ownerToken: ownerToken, claimToken: null, rescueId: rescueId);

            var msg = root.TryGetProperty("message", out var m) ? (m.GetString() ?? "Posted SOS rescue.") : "Posted SOS rescue.";
            return new RescueApiResult<string>(true, id, msg, (int)resp.StatusCode);
        }
        catch (Exception ex)
        {
            return new RescueApiResult<string>(false, null, $"Failed to post SOS rescue: {ex.Message}");
        }
    }

    public async Task<RescueApiResult<string>> ClaimRescueAsync(
        string boardId,
        string rescuerTeamName,
        CancellationToken ct = default)
    {
        if (_offlineMode)
            return OfflineBlocked<string>();

        var team = LauncherPreferences.NormalizeTeamName(rescuerTeamName);
        var payload = JsonSerializer.Serialize(new { rescuer_team_name = team });

        try
        {
            using var content = new StringContent(payload, Encoding.UTF8, "application/json");
            using var resp = await _http.PostAsync($"{_baseUrl}/v1/rescues/{Uri.EscapeDataString(boardId)}/claim", content, ct);
            var body = await resp.Content.ReadAsStringAsync(ct);
            if (!resp.IsSuccessStatusCode)
                return new RescueApiResult<string>(false, null, ExtractError(body, (int)resp.StatusCode), (int)resp.StatusCode);

            using var doc = JsonDocument.Parse(body);
            var root = doc.RootElement;
            var claimToken = REDACTED, out var ctEl) ? ctEl.GetString() : null;
            if (!string.IsNullOrEmpty(claimToken))
                UpsertToken(boardId, ownerToken: null, claimToken: claimToken, rescueId: 0);

            var msg = root.TryGetProperty("message", out var m) ? (m.GetString() ?? "Rescue claimed.") : "Rescue claimed.";
            return new RescueApiResult<string>(true, claimToken, msg, (int)resp.StatusCode);
        }
        catch (Exception ex)
        {
            return new RescueApiResult<string>(false, null, $"Failed to claim rescue: {ex.Message}");
        }
    }

    public async Task<RescueApiResult<string>> CompleteRescueAsync(
        string boardId,
        string aokPassword,
        CancellationToken ct = default)
    {
        RescueMailData decoded;
        try
        {
            decoded = WonderMailCodec.DecodeRescueMail(aokPassword);
        }
        catch (Exception ex)
        {
            return new RescueApiResult<string>(false, null, ex.Message);
        }

        if (!string.Equals(decoded.Kind, "A-OK", StringComparison.Ordinal))
            return new RescueApiResult<string>(false, null, $"Expected an A-OK password, but decoded kind '{decoded.Kind}'.");

        if (_offlineMode)
            return OfflineBlocked<string>();

        var REDACTED = WonderMailCodec.NormalizeAndValidatePassword(aokPassword, 54, "A-OK password");
        var tokens = LoadTokens();
        string? claimToken = REDACTED, out var entry) ? entry.ClaimToken : null;

        var payload = JsonSerializer.Serialize(new
        {
            aok_password = REDACTED,
            claim_token = REDACTED,
        });

        try
        {
            using var content = new StringContent(payload, Encoding.UTF8, "application/json");
            using var resp = await _http.PostAsync($"{_baseUrl}/v1/rescues/{Uri.EscapeDataString(boardId)}/complete", content, ct);
            var body = await resp.Content.ReadAsStringAsync(ct);
            if (!resp.IsSuccessStatusCode)
                return new RescueApiResult<string>(false, null, ExtractError(body, (int)resp.StatusCode), (int)resp.StatusCode);

            using var doc = JsonDocument.Parse(body);
            var msg = doc.RootElement.TryGetProperty("message", out var m)
                ? (m.GetString() ?? "A-OK Mail accepted!")
                : "A-OK Mail accepted!";
            return new RescueApiResult<string>(true, REDACTED, msg, (int)resp.StatusCode);
        }
        catch (Exception ex)
        {
            return new RescueApiResult<string>(false, null, $"Failed to complete rescue: {ex.Message}");
        }
    }

    public async Task<RescueApiResult<string>> SubmitThankYouAsync(
        string boardId,
        string thankYouPassword,
        CancellationToken ct = default)
    {
        RescueMailData decoded;
        try
        {
            decoded = WonderMailCodec.DecodeRescueMail(thankYouPassword);
        }
        catch (Exception ex)
        {
            return new RescueApiResult<string>(false, null, ex.Message);
        }

        if (!string.Equals(decoded.Kind, "THANK-YOU", StringComparison.Ordinal))
            return new RescueApiResult<string>(false, null, $"Expected a THANK-YOU password, but decoded kind '{decoded.Kind}'.");

        if (_offlineMode)
            return OfflineBlocked<string>();

        var REDACTED = WonderMailCodec.NormalizeAndValidatePassword(thankYouPassword, 54, "Thank-You password");
        var tokens = LoadTokens();
        string? ownerToken = REDACTED, out var entry) ? entry.OwnerToken : null;
        if (string.IsNullOrEmpty(ownerToken))
            return new RescueApiResult<string>(false, null, "No owner_token saved on this device for this rescue.");

        var payload = JsonSerializer.Serialize(new
        {
            thank_you_password = REDACTED,
            owner_token = REDACTED,
        });

        try
        {
            using var content = new StringContent(payload, Encoding.UTF8, "application/json");
            using var resp = await _http.PostAsync($"{_baseUrl}/v1/rescues/{Uri.EscapeDataString(boardId)}/thank-you", content, ct);
            var body = await resp.Content.ReadAsStringAsync(ct);
            if (!resp.IsSuccessStatusCode)
                return new RescueApiResult<string>(false, null, ExtractError(body, (int)resp.StatusCode), (int)resp.StatusCode);

            using var doc = JsonDocument.Parse(body);
            var msg = doc.RootElement.TryGetProperty("message", out var m)
                ? (m.GetString() ?? "Thank-You Mail delivered!")
                : "Thank-You Mail delivered!";
            return new RescueApiResult<string>(true, REDACTED, msg, (int)resp.StatusCode);
        }
        catch (Exception ex)
        {
            return new RescueApiResult<string>(false, null, $"Failed to submit Thank-You mail: {ex.Message}");
        }
    }

    private static RescueBoardItem ParseRescueItem(JsonElement el)
    {
        static string GetStr(JsonElement e, string prop, string fallback = "")
            => e.TryGetProperty(prop, out var v) && v.ValueKind == JsonValueKind.String ? (v.GetString() ?? fallback) : fallback;
        static string? GetNullableStr(JsonElement e, string prop)
            => e.TryGetProperty(prop, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : null;
        static int GetInt(JsonElement e, string prop)
            => e.TryGetProperty(prop, out var v) && v.TryGetInt32(out var i) ? i : 0;
        static uint GetUInt(JsonElement e, string prop)
            => e.TryGetProperty(prop, out var v) && v.TryGetUInt32(out var u) ? u : 0u;
        static long GetLong(JsonElement e, string prop)
            => e.TryGetProperty(prop, out var v) && v.TryGetInt64(out var l) ? l : 0L;
        static long? GetNullableLong(JsonElement e, string prop)
            => e.TryGetProperty(prop, out var v) && v.TryGetInt64(out var l) ? l : null;

        return new RescueBoardItem(
            Id: GetStr(el, "id"),
            RescueId: GetUInt(el, "rescue_id"),
            DungeonId: GetInt(el, "dungeon_id"),
            Floor: GetInt(el, "floor"),
            TeamName: GetStr(el, "team_name"),
            ClientSpecies: GetInt(el, "client_species"),
            SosPassword: GetStr(el, "sos_password"),
            AokPassword: GetNullableStr(el, "aok_password"),
            ThankYouPassword: GetNullableStr(el, "thank_you_password"),
            Status: GetStr(el, "status", "open"),
            RescuerTeamName: GetNullableStr(el, "rescuer_team_name"),
            ClaimExpiresAt: GetNullableLong(el, "claim_expires_at"),
            CreatedAt: GetLong(el, "created_at"),
            UpdatedAt: GetLong(el, "updated_at"));
    }

    private static string ExtractError(string body, int statusCode)
    {
        try
        {
            using var doc = JsonDocument.Parse(body);
            if (doc.RootElement.TryGetProperty("error", out var err) && err.ValueKind == JsonValueKind.String)
                return err.GetString() ?? $"HTTP {statusCode}";
        }
        catch
        {
            // Ignore malformed JSON error bodies
        }
        return $"Request failed with HTTP {statusCode}.";
    }
}

