    private RescueBoardService CreateClient()
        => new(EndpointUrl, _tokenStorePath, OfflineOnlyEnabled);

    [RelayCommand]
    private void SelectSubTab(string mode)
    {
        IsOnlineMode = !string.Equals(mode, "offline", StringComparison.OrdinalIgnoreCase);
    }

    [RelayCommand]
    public async Task CheckHealthAsync()
    {
        if (IsBusy) return;
        IsBusy = true;
        HealthStatusText = "Checking...";
        try
        {
            using var client = CreateClient();
            var res = await client.CheckHealthAsync();
            IsServiceOnline = res.Success;
            HealthStatusText = res.Success && res.Data != null
                ? $"Online ({res.Data.Status})"
                : res.Message;
            BoardStatusMessage = res.Success
                ? $"Connected to {client.BaseUrl}"
                : res.Message;
        }
        finally
        {
            IsBusy = false;
        }
    }

    [RelayCommand]
    public async Task RefreshBoardAsync()
    {
        if (IsBusy) return;
        int? dungeonFilter = null;
        var trimmedDungeon = DungeonFilterText.Trim();
        if (!string.IsNullOrEmpty(trimmedDungeon))
        {
            if (!int.TryParse(trimmedDungeon, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) ||
                parsed < 0 || parsed > 127)
            {
                BoardStatusMessage = "Dungeon filter must be an integer between 0 and 127.";
                return;
            }
            dungeonFilter = parsed;
        }

        IsBusy = true;
        var status = StatusFilterChoices[Math.Clamp(SelectedStatusIndex, 0, StatusFilterChoices.Count - 1)];
        try
        {
            using var client = CreateClient();
            var res = await client.ListRescuesAsync(status: status, dungeonId: dungeonFilter);
            if (!res.Success || res.Data == null)
            {
                IsServiceOnline = false;
                BoardStatusMessage = res.Message;
                return;
            }

            IsServiceOnline = true;
            HealthStatusText = "Online";
            var tokens = client.LoadTokens();
            Rescues.Clear();
            foreach (var item in res.Data)
            {
                tokens.TryGetValue(item.Id, out var tok);
                Rescues.Add(new RescueItemViewModel(item, tok, this));
            }
            OnPropertyChanged(nameof(HasRescues));
            OnPropertyChanged(nameof(HasNoRescues));
            BoardStatusMessage = $"Loaded {Rescues.Count} '{status}' rescue(s).";
        }
        finally
        {
            IsBusy = false;
        }
    }

    partial void OnPostSosInputChanged(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            PostSosPreview = "Paste a 54-character SOS password from Explorers of Sky.";
            return;
        }
        try
        {
            var mail = WonderMailCodec.DecodeRescueMail(value);
            PostSosPreview = string.Equals(mail.Kind, "SOS", StringComparison.Ordinal)
                ? $"Valid SOS: Team '{mail.TeamName}' • Dungeon {mail.DungeonId}, {mail.Floor}F • Species #{mail.ClientSpecies} • ID 0x{mail.RescueId:X8}"
                : $"Decoded {mail.Kind} mail (expected SOS for posting).";
        }
        catch (Exception ex)
        {
            PostSosPreview = $"Invalid password: {ex.Message}";
        }
    }

    [RelayCommand]
    public async Task PostSosAsync()
    {
        if (IsBusy) return;
        IsBusy = true;
        try
