    partial void OnDecoderInputChanged(string value) => UpdateDecoder();

    private void UpdateDecoder()
    {
        _lastDecodedRescue = null;
        CanGenerateLinkedAok = false;
        CanGenerateLinkedThankYou = false;

        if (string.IsNullOrWhiteSpace(DecoderInput))
        {
            DecodedKindBadge = "Ready";
            DecodedSummary = "Paste a 34-char Wonder Mail S or 54-char Rescue Mail password to decode and validate.";
            return;
        }

        var compactLen = 0;
        foreach (char c in DecoderInput)
        {
            if (!char.IsWhiteSpace(c)) compactLen++;
        }

        try
        {
            if (compactLen == 34)
            {
                var wm = WonderMailCodec.DecodeWonderMailS(DecoderInput);
                DecodedKindBadge = "Wonder Mail S (34 chars)";
                DecodedSummary = $"Type {wm.Type}.{wm.Subtype} • Dungeon {wm.DungeonId}, Floor {wm.Floor}F\nClient #{wm.ClientId} • Target #{wm.TargetId} • Wanted #{wm.ItemWanted} • Reward #{wm.ItemReward} (type {wm.RewardType})";
                return;
            }

            if (compactLen == 54)
            {
                var mail = WonderMailCodec.DecodeRescueMail(DecoderInput);
                _lastDecodedRescue = mail;
                DecodedKindBadge = $"Friend Rescue: {mail.Kind}";
                DecodedSummary = $"Team: {mail.TeamName} • Dungeon {mail.DungeonId}, Floor {mail.Floor}F\nClient Species: #{mail.ClientSpecies} • Rescue ID: 0x{mail.RescueId:X8} • Revives Left: {mail.RevivesLeft}";
                CanGenerateLinkedAok = string.Equals(mail.Kind, "SOS", StringComparison.Ordinal) && mail.RevivesLeft > 0;
                CanGenerateLinkedThankYou = string.Equals(mail.Kind, "A-OK", StringComparison.Ordinal);
                return;
            }

            DecodedKindBadge = $"Invalid Length ({compactLen})";
            DecodedSummary = $"Expected 34 characters (Wonder Mail S) or 54 characters (Friend Rescue), got {compactLen}.";
        }
        catch (Exception ex)
        {
            DecodedKindBadge = "Validation Failed";
            DecodedSummary = ex.Message;
        }
    }

    [RelayCommand]
    private void GenerateLinkedAok()
    {
        if (_lastDecodedRescue == null) return;
        try
        {
            var aok = WonderMailCodec.CreateAokFromSos(_lastDecodedRescue, StudioTeamName);
            var encoded = WonderMailCodec.EncodeRescueMail(aok);
            GeneratedPassword = WonderMailCodec.FormatMultiline(encoded, 18);
            StudioStatusMessage = $"Generated linked A-OK Mail for Team '{aok.TeamName}' (ID 0x{aok.RescueId:X8}).";
        }
        catch (Exception ex)
        {
            StudioStatusMessage = ex.Message;
