    [RelayCommand]
    private void RandomizeRescueId()
    {
        uint next = (uint)Random.Shared.NextInt64(1, 0xFFFFFFFFL);
        GenRescueIdHex = next.ToString("X8", CultureInfo.InvariantCulture);
    }

    [RelayCommand]
    private void GenerateSos()
    {
        if (!TryParseGeneratorInputs(out int dungeon, out int floor, out int species, out uint rescueId, out int revives, out string err))
        {
            StudioStatusMessage = err;
            return;
        }

        try
        {
            var mail = new RescueMailData
            {
                Kind = "SOS",
                DungeonId = dungeon,
                Floor = floor,
                TeamName = LauncherPreferences.NormalizeTeamName(StudioTeamName),
                ClientSpecies = species,
                RescueId = rescueId,
                RevivesLeft = revives,
            };
            var encoded = WonderMailCodec.EncodeRescueMail(mail);
            GeneratedPassword = WonderMailCodec.FormatMultiline(encoded, 18);
            DecoderInput = GeneratedPassword;
            StudioStatusMessage = $"Generated 54-char SOS Mail (ID 0x{rescueId:X8}).";
        }
        catch (Exception ex)
        {
            StudioStatusMessage = ex.Message;
        }
    }

    [RelayCommand]
    private void GenerateWonderMailS()
    {
        if (!TryParseGeneratorInputs(out int dungeon, out int floor, out int species, out _, out _, out string err))
        {
            StudioStatusMessage = err;
            return;
        }

        try
        {
            var mission = new MissionData
            {
                Type = 1,
                Subtype = 0,
                DungeonId = dungeon,
                Floor = floor,
                ClientId = species,
                TargetId = species,
                ItemWanted = 0,
                RewardType = 1,
                ItemReward = 105,
            };
            var encoded = WonderMailCodec.EncodeWonderMailS(mission);
            GeneratedPassword = WonderMailCodec.FormatMultiline(encoded, 17);
            DecoderInput = GeneratedPassword;
            StudioStatusMessage = $"Generated 34-char Wonder Mail S code for Dungeon {dungeon}, {floor}F.";
        }
        catch (Exception ex)
        {
            StudioStatusMessage = ex.Message;
        }
    }

    private bool TryParseGeneratorInputs(
        out int dungeon, out int floor, out int species, out uint rescueId, out int revives, out string error)
    {
        dungeon = 1;
        floor = 1;
        species = 25;
        rescueId = 0x12345678u;
        revives = 3;

        if (!int.TryParse(GenDungeonIdText.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out dungeon) || dungeon < 0 || dungeon > 127)
        {
            error = "Dungeon ID must be in [0..127].";
            return false;
        }
        if (!int.TryParse(GenFloorText.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out floor) || floor < 0 || floor > 127)
        {
            error = "Floor must be in [0..127].";
            return false;
        }
        if (!int.TryParse(GenSpeciesText.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out species) || species < 0 || species > 2047)
        {
            error = "Species ID must be in [0..2047].";
            return false;
        }
        var hex = GenRescueIdHex.Trim();
        if (hex.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
            hex = hex[2..];
        if (!uint.TryParse(hex, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out rescueId))
        {
            error = "Rescue ID must be a valid 32-bit hex value (e.g. 12345678).";
            return false;
        }
        if (!int.TryParse(GenRevivesText.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out revives) || revives < 0 || revives > 7)
        {
            error = "Revives Left must be in [0..7].";
            return false;
        }
        error = "";
        return true;
    }

    [RelayCommand]
    private Task CopyGeneratedAsync() => HasGeneratedPassword
        ? CopyTextAsync(GeneratedPassword, "Copied generated password to clipboard.")
        : Task.CompletedTask;

    public async Task CopyTextAsync(string text, string successMessage)
    {
        if (CopyToClipboardAsync == null)
        {
            BoardStatusMessage = "Clipboard handler is unavailable.";
            StudioStatusMessage = "Clipboard handler is unavailable.";
            return;
        }
        await CopyToClipboardAsync(text);
        BoardStatusMessage = successMessage;
        StudioStatusMessage = successMessage;
    }
}

