    private sealed class MockRescueHandler : HttpMessageHandler
    {
        public int RequestCount { get; private set; }
        public string? LastCompleteClaimToken { get; private set; }
        public string? LastThankYouOwnerToken { get; private set; }

        private readonly string _boardId = "11111111-2222-3333-4444-555555555555";
        private string _status = "open";
        private string _sos = "";
        private string? _aok;
        private string? _ty;
        private uint _rescueId;

        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
        {
            RequestCount++;
            var path = request.RequestUri?.AbsolutePath ?? "";
            var body = request.Content != null ? await request.Content.ReadAsStringAsync(cancellationToken) : "";

            if (request.Method == HttpMethod.Get && path == "/health")
            {
                return JsonResp(HttpStatusCode.OK, "{\"status\":\"healthy\",\"service\":\"MockBoard\",\"timestamp\":1700000000}");
            }

            if (request.Method == HttpMethod.Post && path == "/v1/rescues")
            {
                using var doc = JsonDocument.Parse(body);
                _sos = doc.RootElement.GetProperty("sos_password").GetString()!;
                _rescueId = WonderMailCodec.DecodeRescueMail(_sos).RescueId;
                _status = "open";
                return JsonResp(HttpStatusCode.Created, $"{{\"success\":true,\"id\":\"{_boardId}\",\"rescue_id\":{_rescueId},\"owner_token\":\"own-tok-123\",\"status\":\"open\",\"message\":\"Posted!\"}}");
            }

            if (request.Method == HttpMethod.Get && path == "/v1/rescues")
            {
                var item = new
                {
                    id = _boardId,
                    rescue_id = _rescueId,
                    dungeon_id = 24,
                    floor = 15,
                    team_name = "Explorers",
                    client_species = 25,
                    sos_password = _sos,
                    aok_password = _aok,
                    thank_you_password = _ty,
                    status = _status,
                    rescuer_team_name = "Saviors",
                    created_at = 1700000000,
                    updated_at = 1700000001,
                };
                return JsonResp(HttpStatusCode.OK, JsonSerializer.Serialize(new { success = true, rescues = new[] { item } }));
            }

            if (request.Method == HttpMethod.Post && path == $"/v1/rescues/{_boardId}/claim")
            {
                _status = "claimed";
                return JsonResp(HttpStatusCode.OK, $"{{\"success\":true,\"id\":\"{_boardId}\",\"status\":\"claimed\",\"claim_token\":\"claim-tok-456\",\"message\":\"Claimed!\"}}");
            }

            if (request.Method == HttpMethod.Post && path == $"/v1/rescues/{_boardId}/complete")
            {
                using var doc = JsonDocument.Parse(body);
                LastCompleteClaimToken = REDACTED, out var ctEl) ? ctEl.GetString() : null;
                _aok = doc.RootElement.GetProperty("aok_password").GetString();
                _status = "completed";
                return JsonResp(HttpStatusCode.OK, $"{{\"success\":true,\"id\":\"{_boardId}\",\"status\":\"completed\",\"message\":\"Completed!\"}}");
            }

            if (request.Method == HttpMethod.Post && path == $"/v1/rescues/{_boardId}/thank-you")
            {
