                return JsonResp(HttpStatusCode.OK, $"{{\"success\":true,\"id\":\"{_boardId}\",\"status\":\"completed\",\"thank_you_recorded\":true,\"message\":\"Thank-You recorded!\"}}");
            }

            return JsonResp(HttpStatusCode.NotFound, "{\"error\":\"Not found\"}");
        }

