    private static async Task TestRescueBoardServiceAsync()
    {
        using var tmp = new TempDir();
        var tokenPath = Path.Combine(tmp.Path, "rescue_tokens.json");
        var handler = new MockRescueHandler();

        var sos = new RescueMailData
        {
            Kind = "SOS",
            DungeonId = 24,
            Floor = 15,
            TeamName = "Explorers",
            ClientSpecies = 25,
            RescueId = 0x1234ABCDu,
            RevivesLeft = 3,
        };
        var sosPwd = WonderMailCodec.EncodeRescueMail(sos);
        var aokPwd = WonderMailCodec.EncodeRescueMail(WonderMailCodec.CreateAokFromSos(sos, "Saviors"));
        var tyPwd = WonderMailCodec.EncodeRescueMail(WonderMailCodec.CreateThankYouFromAok(WonderMailCodec.DecodeRescueMail(aokPwd), "Explorers"));

        // Offline mode must block all network calls
        using (var offlineClient = new RescueBoardService("https://example.invalid", tokenPath, offlineMode: true, handler))
        {
            var healthOffline = await offlineClient.CheckHealthAsync();
            Assert(!healthOffline.Success, "Offline check should fail cleanly");
            AssertEqual(handler.RequestCount, 0, "Zero HTTP requests made in offline mode");
        }

        using var client = new RescueBoardService("https://board.example.test", tokenPath, offlineMode: false, handler);
        var health = await client.CheckHealthAsync();
        Assert(health.Success && health.Data?.Status == "healthy", "Health check succeeds");

        var postRes = await client.PostSosRescueAsync(sosPwd);
        Assert(postRes.Success, "Post SOS succeeds");
        var boardId = postRes.Data!;

        var listRes = await client.ListRescuesAsync("open");
        Assert(listRes.Success && listRes.Data?.Count == 1, "List rescues returns posted item");

        var claimRes = await client.ClaimRescueAsync(boardId, "Saviors");
        Assert(claimRes.Success, "Claim succeeds");

        var tokens = client.LoadTokens();
        AssertEqual(tokens[boardId].OwnerToken, "own-tok-123", "Owner token persisted");
        AssertEqual(tokens[boardId].ClaimToken, "claim-tok-456", "Claim token persisted");

        var completeRes = await client.CompleteRescueAsync(boardId, aokPwd);
        Assert(completeRes.Success, "Complete succeeds");
        AssertEqual(handler.LastCompleteClaimToken, "claim-tok-456", "Stored claim_token sent on complete");

        var tyRes = await client.SubmitThankYouAsync(boardId, tyPwd);
        Assert(tyRes.Success, "Thank-You succeeds");
        AssertEqual(handler.LastThankYouOwnerToken, "own-tok-123", "Stored owner_token sent on thank-you");
    }

    private static void TestSaveManagementService()
    {
        using var tmp = new TempDir();
        var savesDir = Path.Combine(tmp.Path, "saves");
        var statesDir = Path.Combine(tmp.Path, "savestates");
        Directory.CreateDirectory(savesDir);
        Directory.CreateDirectory(statesDir);
        File.WriteAllBytes(Path.Combine(statesDir, "slot1.ss0"), new byte[] { 1, 2, 3 });

        var missingInfo = SaveManagementService.InspectSave(savesDir, statesDir);
        Assert(!missingInfo.Exists, "Missing save reported");
        AssertEqual(missingInfo.SavestateCount, 1, "Savestate count");

        // Create valid 128 KiB EEPROM save
        var savePath = SaveManagementService.GetSaveFilePath(savesDir);
        var originalSave = new byte[SaveManagementService.ExpectedEepromSaveBytes];
        Array.Fill(originalSave, (byte)0x42);
        File.WriteAllBytes(savePath, originalSave);

        var validInfo = SaveManagementService.InspectSave(savesDir, statesDir);
        Assert(validInfo.Exists && validInfo.IsValidEepromSize, "131072-byte EEPROM save is valid");
        AssertEqual(validInfo.Sha256Short.Length, 16, "SHA-256 prefix length");

        var backup = SaveManagementService.CreateBackup(savesDir);
        Assert(backup.IsValidEepromSize, "Backup has valid 128 KiB size");
        AssertEqual(SaveManagementService.ListBackups(savesDir).Count, 1, "One backup listed");

        // Modify active save, then restore -> safety pre-restore backup created + original bytes restored
        var modifiedSave = new byte[SaveManagementService.ExpectedEepromSaveBytes];
        Array.Fill(modifiedSave, (byte)0x99);
        File.WriteAllBytes(savePath, modifiedSave);

        SaveManagementService.RestoreBackup(backup.FullPath, savesDir);
        Assert(File.ReadAllBytes(savePath).SequenceEqual(originalSave), "Active save restored to original bytes");
        AssertEqual(SaveManagementService.ListBackups(savesDir).Count, 2, "Pre-restore safety backup created");

        // Reject invalid-size backup restore
        var corruptBackup = Path.Combine(SaveManagementService.GetBackupsDir(savesDir), "corrupt.sav");
        File.WriteAllBytes(corruptBackup, new byte[] { 1, 2, 3, 4 });
        AssertThrows<InvalidDataException>(
            () => SaveManagementService.RestoreBackup(corruptBackup, savesDir),
            "Refuse corrupted non-128KiB save restore");
    }
}

